source:
import { useEffect, useState } from 'react';
import type { ReactNode } from 'react';
import { useErroToast } from '../layout/use-erro-toast';
import type { ResultadoPaginado } from '../../services/constant/type/paginacao.type';
import type { LogAuditoriaResponse, OperacaoLogAuditoria } from '../../services/27-log-auditoria/type/log-auditoria.type';

// Parcial de propósito: 'EXPORT' não tem rótulo próprio aqui - o `??
// linha.operacao` na leitura já cobre esse (e qualquer outro) caso
// ausente, mesmo comportamento de antes.
const ROTULO_OPERACAO: Partial<Record<OperacaoLogAuditoria, string>> = {
  INSERT: 'Criado',
  UPDATE: 'Alterado',
  DELETE: 'Excluído',
};

// `dadosAnteriores`/`dadosNovos` guardam snapshot genérico da linha
// (Record<string, unknown>) - não dá pra jogar `unknown` direto num filho
// JSX. Na prática `campoRenomeio` é sempre um campo textual (ex.: "nome"),
// então isto só cai no `String(valor)` num caso que nunca acontece de
// verdade - mesmo padrão de `celulaValor` em generic-table.tsx.
function valorRenomeio(valor: unknown): ReactNode {
  if (valor === null || valor === undefined) {
    return '-';
  }
  if (typeof valor === 'string' || typeof valor === 'number' || typeof valor === 'boolean') {
    return valor;
  }
  return String(valor);
}

interface LogAuditoriaPainelProps {
  buscar: (pagina: number) => Promise<ResultadoPaginado<LogAuditoriaResponse>>;
  campoRenomeio?: string;
}

// Painel "Ver log" (pedido do Lucas, 03-08-2026: "um botão no fundo de
// cada tabela... pra vermos a última alteração") - vive dentro de
// GenericTable, só busca quando abre (`buscar` é a mesma convenção de
// `listar` do GenericTable: função já vem pronta, pré-amarrada com
// authFetch e o nome da tabela, pelo componente pai). Mostra as últimas
// alterações de UMA tabela física (log_auditoria.tabela), mais recente
// primeiro - não filtra por registro específico ainda (isso seria um 2º
// botão, "Ver log deste registro", dentro de Consultar - fica pra quando
// o Lucas quiser essa granularidade).
//
// `campoRenomeio` (09-08-2026, pedido do Lucas: "log da tabela Papéis com
// duas colunas, nome antigo e nome atual") - opt-in, não específico de
// papel: quando informado (ex.: "nome"), troca a coluna genérica "Campos
// alterados" por duas colunas de verdade ("De"/"Para") lendo o valor
// daquele campo em `dadosAnteriores`/`dadosNovos` (o log_auditoria já
// grava a linha inteira antes/depois, não precisou de coluna nova no
// banco - só o React passou a ler o que já existia). Lucas comentou que
// esse conceito serve pra outros logs no futuro - qualquer tela que
// passe `buscarLog`/`campoRenomeioLog` pro GenericTable ganha o mesmo
// recurso de graça, não é hardcoded pra papel.
export function LogAuditoriaPainel({ buscar, campoRenomeio }: LogAuditoriaPainelProps) {
  const [linhas, setLinhas] = useState<LogAuditoriaResponse[]>([]);
  const [total, setTotal] = useState(0);
  const [tamanho, setTamanho] = useState(20);
  // Página (11-08-2026, achado da parceira do Lucas: "vai virar aquela
  // listona conforme o sistema cresce") - o backend já paginava de
  // verdade (LIMIT/OFFSET), só o painel nunca pedia página nenhuma além
  // da 1ª.
  const [pagina, setPagina] = useState(1);
  const [carregando, setCarregando] = useState(true);
  const { erro, reportarErro, limparErro } = useErroToast();

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setCarregando(true);
    limparErro();
    buscar(pagina)
      .then((resposta) => {
        setLinhas(resposta.dados);
        setTotal(resposta.total);
        setTamanho(resposta.tamanho);
      })
      .catch(reportarErro)
      .finally(() => setCarregando(false));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [buscar, pagina]);

  const totalPaginas = Math.max(1, Math.ceil(total / tamanho));

  return (
    <div className="mt-4 border-t borda-padrao pt-4">
      <h3 className="text-sm font-bold texto-padrao mb-2">
        Últimas alterações {total > 0 && `(${total} no total)`}
      </h3>

      {carregando && <p className="text-sm texto-fraco">Carregando...</p>}
      {erro && <p className="crud-erro">{erro}</p>}

      {!carregando && !erro && (
        <table className="crud-tabela">
          <thead>
            <tr>
              {/* Registro antes de Ação (09-08-2026, pedido do Lucas: "fica
                  mais bonito o registro vindo primeiro") - mesma ordem nos
                  dois <tr>, cabeçalho e corpo. */}
              <th>Registro</th>
              <th>Ação</th>
              {campoRenomeio ? (
                <>
                  <th>De</th>
                  <th>Para</th>
                </>
              ) : (
                <th>Campos alterados</th>
              )}
              <th>Quem</th>
              <th>Quando</th>
            </tr>
          </thead>
          <tbody>
            {linhas.map((linha) => (
              <tr key={linha.idLog}>
                <td>{linha.identidadeRegistro}</td>
                <td>{ROTULO_OPERACAO[linha.operacao] ?? linha.operacao}</td>
                {campoRenomeio ? (
                  <>
                    <td>{valorRenomeio(linha.dadosAnteriores?.[campoRenomeio])}</td>
                    <td>{valorRenomeio(linha.dadosNovos?.[campoRenomeio])}</td>
                  </>
                ) : (
                  <td>{linha.camposAlterados ? linha.camposAlterados.join(', ') : ''}</td>
                )}
                <td>{linha.nomeResponsavel ?? 'Sistema'}</td>
                <td>{new Date(linha.ocorridoEm).toLocaleString('pt-BR')}</td>
              </tr>
            ))}
            {linhas.length === 0 && (
              <tr>
                <td colSpan={campoRenomeio ? 6 : 5}>Nenhuma alteração registrada ainda.</td>
              </tr>
            )}
          </tbody>
        </table>
      )}

      {!carregando && !erro && totalPaginas > 1 && (
        <div className="flex items-center justify-between flex-wrap gap-3 mt-3 text-sm texto-padrao">
          <span>
            Página {pagina} de {totalPaginas} ({total} no total)
          </span>
          <div className="flex gap-2">
            <button
              type="button"
              onClick={() => setPagina((p) => Math.max(1, p - 1))}
              disabled={pagina === 1}
              className="btn btn-secondary"
            >
              Anterior
            </button>
            <button
              type="button"
              onClick={() => setPagina((p) => Math.min(totalPaginas, p + 1))}
              disabled={pagina === totalPaginas}
              className="btn btn-secondary"
            >
              Próxima
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

import type { ReactNode } from 'react';

// Modal genérico de "detalhe explicado" (09-08-2026, Bloco F do prompt do
// uma IA) - nasceu pra explicar uma permissão (o quê, por que existe,
// quem tem hoje), mas não tem nada específico de permissão aqui: título,
// legenda em fonte mono (a "chave" técnica), um badge opcional e uma lista
// de seções título+conteúdo. Feito pra ser reaproveitado depois pra
// explicar configuração, papel, status de campanha etc - quem muda é só
// o conteúdo das seções, não este componente.
type ImpactoBadge = 'alto' | 'médio' | 'baixo';

const CLASSE_BADGE_IMPACTO: Record<ImpactoBadge, string> = {
  alto: 'fundo-erro texto-erro',
  médio: 'fundo-aviso texto-aviso',
  baixo: 'fundo-info texto-info',
};

interface SecaoModalDetalhe {
  titulo: string;
  conteudo: ReactNode;
}

interface ModalDetalheProps {
  titulo: string;
  chave?: string;
  badgeImpacto?: ImpactoBadge | null;
  secoes: SecaoModalDetalhe[];
  aoFechar: () => void;
  rotuloAcao?: string;
}

// `rotuloAcao` (23-08-2026, Campo de Testes: "Consultar" de Link
// Acadêmico) - cabeçalho extra, opcional, grande/centralizado/maiúsculo
// + linha divisória, ANTES do título normal (achado do Lucas: um
// "Consultar" precisa deixar claro de cara que ação é essa, antes de
// entrar nos detalhes de qual registro). Sem essa prop, o modal continua
// exatamente como sempre foi (Permissões nunca passou isso).
export function ModalDetalhe({
  titulo,
  chave,
  badgeImpacto,
  secoes,
  aoFechar,
  rotuloAcao,
}: ModalDetalheProps) {
  return (
    <div
      className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/40"
      onClick={aoFechar}
    >
      <div
        className="w-full max-w-lg max-h-[85vh] fundo-elevado rounded-2xl shadow-2xl border borda-forte overflow-hidden flex flex-col"
        onClick={(evento) => evento.stopPropagation()}
      >
        {rotuloAcao && (
          <>
            <div className="px-6 pt-5 pb-3 flex items-center justify-between gap-3 shrink-0">
              <span className="w-4"></span>
              <p className="text-center font-black uppercase tracking-widest texto-forte text-lg">{rotuloAcao}</p>
              <button
                type="button"
                onClick={aoFechar}
                aria-label="Fechar"
                className="texto-fraco hover-texto-forte"
              >
                <i className="fa-solid fa-xmark"></i>
              </button>
            </div>
            <div className="border-t borda-padrao"></div>
          </>
        )}

        <div className={'px-6 py-4 flex items-start justify-between gap-3 shrink-0' + (rotuloAcao ? '' : ' border-b borda-padrao')}>
          <div className="min-w-0">
            <p className="font-bold texto-forte truncate">{titulo}</p>
            {chave && <p className="paragrafo-denso mt-0.5">{chave}</p>}
          </div>
          <div className="flex items-center gap-3 shrink-0">
            {badgeImpacto && (
              <span
                className={
                  'text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full ' +
                  (CLASSE_BADGE_IMPACTO[badgeImpacto] ?? 'fundo-sutil texto-fraco')
                }
              >
                Impacto {badgeImpacto}
              </span>
            )}
            {!rotuloAcao && (
              <button
                type="button"
                onClick={aoFechar}
                aria-label="Fechar"
                className="texto-fraco hover-texto-forte"
              >
                <i className="fa-solid fa-xmark"></i>
              </button>
            )}
          </div>
        </div>

        <div className="px-6 py-4 overflow-y-auto space-y-4">
          {secoes.map((secao) => (
            <div key={secao.titulo}>
              <h4 className="text-xs font-bold uppercase tracking-widest texto-fraco mb-1.5">
                {secao.titulo}
              </h4>
              {/* ERA texto-padrao (slate-700) - muito claro pro corpo
                  principal do modal (09-08-2026, achado do Lucas: "o texto
                  deste dialogbox está muito cinza"). texto-forte é o mesmo
                  tom do título (slate-800/quase-branco no escuro), sem
                  perder a hierarquia com o rótulo da seção (que continua
                  texto-fraco, acima). */}
              <div className="text-sm texto-forte">{secao.conteudo}</div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import { useRef, useState } from 'react';
import type { ChangeEvent } from 'react';
import { AvatarUsuario } from '../layout/avatar-usuario';
import type { TamanhoAvatar } from '../layout/avatar-usuario';
import { ErroHttp } from '../../services/constant/api/http.util';
import { traduzirErro } from '../../services/constant/api/traduzir-erro.util';
import { arquivoApi } from '../../services/25-arquivo/api/arquivo.api';
import { reduzirImagemNoNavegador } from '../../services/25-arquivo/util/reduzir-imagem.util';
import { useConfiguracoes } from '../../services/11-configuracoes/hook/use-configuracoes';
import type { AuthFetch } from '../../services/3-auth/type/auth.type';

// Espelha a lista aceita no backend (nest/src/25-arquivo/arquivo.constants.ts
// TIPOS_MIME_PERMITIDOS) - MENOS application/pdf, que não faz sentido como
// foto de perfil. Se um dia o backend mudar essa lista, mudar aqui também;
// isto é só uma checagem CLIENTE (evita round-trip óbvio), o backend
// confere de novo (e de verdade - assinatura mágica dos bytes) na
// confirmação, então errar aqui não é um risco de segurança, só uma UX
// pior (erro só depois de enviar). Não é config - é lista estrutural do
// que o processamento de imagem (`sharp`) sabe converter, não regra de
// negócio editável pelo Admin.
const TIPOS_AVATAR_PERMITIDOS = ['image/jpeg', 'image/png', 'image/webp'];
// Teto BRUTO (antes da redução) - só pra recusar algo absurdo cedo (ex.:
// vídeo de 300MB renomeado pra .jpg) sem gastar CPU tentando processar no
// canvas; não tem relação com o teto real do backend (abaixo, via config).
const TAMANHO_MAXIMO_BRUTO_BYTES = 30 * 1024 * 1024;
// Mesmos números do perfil 'avatar' em PERFIL_PROCESSAMENTO_POR_CONTEXTO
// (nest/src/25-arquivo/arquivo.constants.ts) - sem import cruzado entre
// os repositórios, mantenha os dois em sincronia manualmente se mudar.
const PERFIL_REDUCAO_AVATAR = { larguraMaxima: 512, qualidade: 80 };

// Avatar EDITÁVEL - usa <AvatarUsuario> por baixo pra desenhar a bolinha
// (foto ou inicial colorida, sem duplicar essa lógica), e adiciona por
// cima: o botãozinho de câmera, o <input type="file"> escondido, o botão
// de remover (só aparece quando já existe uma foto), e o fluxo de upload
// de 3 passos inteiro (iniciar -> enviar pro bucket -> confirmar -> devolve
// o novo id/URL pro componente pai via `aoAlterar`).
//
// Este componente NUNCA salva nada em `usuario` sozinho - ele só sobe (ou
// sinaliza a remoção d)o arquivo e devolve o resultado pro pai via
// `aoAlterar`. Quem usa isto (criar-usuario.jsx, alterar-usuario.jsx,
// minha-conta-page.jsx) decide quando mandar isso pro backend (no create,
// ou no PATCH de alterar/Minha Conta) - mesma separação de
// responsabilidade do resto do app (componente de input nunca chama
// usuarioApi diretamente).
//
// `aoAlterar(idArquivo, novaUrl)` - foto nova escolhida (upload já
// confirmado no backend). `aoAlterar(null, null)` (25-08-2026, "Remover
// foto") - pessoa pediu pra tirar a foto atual; quem usa este componente
// distingue "nenhuma escolha feita ainda" (não chamou aoAlterar) de
// "removida de propósito" (chamou com null) guardando o id como
// `undefined` por padrão, nunca `null`, exatamente pra sobrar esse
// terceiro estado - ver alterar-usuario.jsx/minha-conta-page.jsx.
interface SeletorFotoPerfilProps {
  authFetch: AuthFetch;
  nome?: string | null;
  url?: string | null;
  aoAlterar: (idArquivo: number | null, url: string | null) => void;
  tamanho?: TamanhoAvatar;
  desabilitado?: boolean;
}

export function SeletorFotoPerfil({
  authFetch,
  nome,
  url,
  aoAlterar,
  tamanho = 'xl',
  desabilitado = false,
}: SeletorFotoPerfilProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [enviando, setEnviando] = useState(false);
  const [erroLocal, setErroLocal] = useState('');

  // `arquivo_tamanho_maximo_imagem_bytes` já vive em `configuracoes`
  // (marcada `publica`, 05-09-2026) - lida daqui em vez de duplicada à mão
  // (era `8 * 1024 * 1024` fixo neste arquivo, e no Nest ao mesmo tempo,
  // sincronizados só de boa vontade). O valor padrão abaixo é só o que
  // aparece por uma fração de segundo antes do `ConfiguracoesProvider`
  // terminar de carregar - depois disso, sempre reflete o que o Admin
  // configurou.
  const { obterConfiguracao } = useConfiguracoes();
  const valorConfigurado = obterConfiguracao('arquivo_tamanho_maximo_imagem_bytes', 8 * 1024 * 1024);
  // `obterConfiguracao` devolve `string | number | boolean | null` (o
  // armazém de config guarda tipos heterogêneos) - narrow explícito em vez
  // de confiar que esta chave específica é sempre numérica, mesmo default
  // (8 * 1024 * 1024) preservado exatamente como padrão de verdade.
  const tamanhoMaximoAvatarBytes = typeof valorConfigurado === 'number' ? valorConfigurado : 8 * 1024 * 1024;

  const processarArquivo = async (arquivoEscolhido: File) => {
    setErroLocal('');

    if (!TIPOS_AVATAR_PERMITIDOS.includes(arquivoEscolhido.type)) {
      setErroLocal('Formato não aceito. Envie um JPEG, PNG ou WebP.');
      return;
    }
    if (arquivoEscolhido.size > TAMANHO_MAXIMO_BRUTO_BYTES) {
      setErroLocal('Imagem muito grande pra processar.');
      return;
    }

    setEnviando(true);
    try {
      // Reduz no navegador ANTES de subir (Canvas API, 01-09-2026) - upload
      // mais rápido numa conexão ruim e menos risco da URL pré-assinada (5
      // min de validade) expirar no meio do envio. Se falhar por qualquer
      // motivo (navegador sem suporte, etc.), devolve o arquivo original
      // sem quebrar o fluxo - ver reduzir-imagem.util.js. O backend
      // continua processando de novo com `sharp` de qualquer jeito, então
      // isto é só uma otimização de UX, nunca a autoridade final.
      const arquivo = await reduzirImagemNoNavegador(
        arquivoEscolhido,
        PERFIL_REDUCAO_AVATAR,
      );

      if (arquivo.size > tamanhoMaximoAvatarBytes) {
        // `finally` abaixo cuida de setEnviando(false) neste return também.
        // Mensagem calcula o MB a partir da config (não hardcoded) - se o
        // Admin mudar `arquivo_tamanho_maximo_imagem_bytes`, o texto some
        // sozinho.
        const megabytes = Math.round(tamanhoMaximoAvatarBytes / (1024 * 1024));
        setErroLocal(`Imagem muito grande - o tamanho máximo é ${megabytes} MB.`);
        return;
      }

      const uploadPreAssinado = await arquivoApi.iniciarUpload(authFetch, {
        nomeOriginal: arquivo.name,
        tipoMime: arquivo.type,
        tamanhoBytes: arquivo.size,
      });

      await arquivoApi.enviarParaBucket(uploadPreAssinado, arquivo);

      const arquivoConfirmado = await arquivoApi.confirmarUpload(authFetch, {
        chave: uploadPreAssinado.chave,
        nomeOriginal: arquivo.name,
        tipoMime: arquivo.type,
        tamanhoBytes: arquivo.size,
        // Diz ao backend qual teto de redimensionamento usar (512px pra
        // avatar) - ver PERFIL_PROCESSAMENTO_POR_CONTEXTO em
        // nest/src/25-arquivo/arquivo.constants.ts.
        contexto: 'avatar',
      });

      aoAlterar(arquivoConfirmado.idArquivo, arquivoConfirmado.url);
    } catch (erroRequisicao) {
      // ErroHttp (traduzirErro) só cobre erro de VERDADE do backend
      // (iniciar/confirmar) - validação local e falha de rede no PUT pro
      // bucket (arquivoApi.enviarParaBucket) já lançam com mensagem própria
      // em português; passar essas por traduzirErro as trocaria pela
      // mensagem genérica de "não foi possível falar com o servidor" (ver
      // traduzir-erro.util.js), que aqui seria enganosa.
      setErroLocal(
        erroRequisicao instanceof ErroHttp
          ? traduzirErro(erroRequisicao)
          : erroRequisicao instanceof Error
            ? erroRequisicao.message
            : String(erroRequisicao),
      );
    } finally {
      setEnviando(false);
    }
  };

  const aoSelecionarArquivo = (evento: ChangeEvent<HTMLInputElement>) => {
    const arquivo = evento.target.files?.[0];
    // Zera o valor do input - sem isso, escolher o MESMO arquivo duas vezes
    // seguidas (ex.: tentou, deu erro de tamanho, cortou a imagem, tentou
    // de novo com o mesmo nome) não dispara onChange na segunda vez.
    evento.target.value = '';
    if (arquivo) {
      processarArquivo(arquivo);
    }
  };

  // Remover foto (25-08-2026, pedido do Lucas: "botão simples pra remover
  // a foto, arquivo, tudo limpo") - não apaga nada AQUI, só sinaliza a
  // intenção pro pai (aoAlterar(null, null)); o arquivo de verdade (linha
  // desativada + bytes apagados do bucket) só some quando quem usa este
  // componente salvar de fato (PATCH /usuario com idImagemPerfil: null -
  // usuario.service.update.ts já cuida da limpeza, mesmo caminho que já
  // desativa a foto ANTIGA ao trocar por uma nova).
  const aoRemover = () => {
    if (!window.confirm('Remover a foto de perfil?')) {
      return;
    }
    setErroLocal('');
    aoAlterar(null, null);
  };

  return (
    <div>
      <div className="relative inline-block">
        <AvatarUsuario nome={nome} foto={url} tamanho={tamanho} forma="circulo" />

        {enviando && (
          <div className="absolute inset-0 rounded-full flex items-center justify-center bg-black/50 text-white">
            <i className="fa-solid fa-spinner fa-spin"></i>
          </div>
        )}

        {!desabilitado && (
          <button
            type="button"
            onClick={() => inputRef.current?.click()}
            disabled={enviando}
            aria-label="Alterar foto de perfil"
            title="Alterar foto de perfil"
            className="absolute -bottom-1 -right-1 w-7 h-7 rounded-full bg-dark hover:bg-black text-white flex items-center justify-center text-xs border-2 border-white shadow transition-colors disabled:opacity-60"
          >
            <i className="fa-solid fa-camera"></i>
          </button>
        )}

        {!desabilitado && url && (
          <button
            type="button"
            onClick={aoRemover}
            disabled={enviando}
            aria-label="Remover foto de perfil"
            title="Remover foto de perfil"
            className="absolute -bottom-1 -left-1 w-7 h-7 rounded-full bg-red-600 hover:bg-red-700 text-white flex items-center justify-center text-xs border-2 border-white shadow transition-colors disabled:opacity-60"
          >
            <i className="fa-solid fa-trash"></i>
          </button>
        )}

        <input
          ref={inputRef}
          type="file"
          accept={TIPOS_AVATAR_PERMITIDOS.join(',')}
          className="hidden"
          onChange={aoSelecionarArquivo}
        />
      </div>

      {erroLocal && <p className="text-red-700 text-xs font-bold mt-1.5 max-w-[10rem]">{erroLocal}</p>}
    </div>
  );
}

const PALETA_AVATAR: string[] = [
  'var(--cor-avatar-1)',
  'var(--cor-avatar-2)',
  'var(--cor-avatar-3)',
  'var(--cor-avatar-4)',
  'var(--cor-avatar-5)',
  'var(--cor-avatar-6)',
  'var(--cor-avatar-7)',
];

// Hash simples (soma de código de caractere) - DETERMINÍSTICO de propósito
// (09-08-2026, Bloco B/C): a mesma pessoa cai sempre na mesma cor, em
// qualquer tela/sessão, sem guardar nada no banco. Nada de Math.random().
function corPorNome(nome: string): string {
  let soma = 0;
  for (let i = 0; i < nome.length; i += 1) {
    soma += nome.charCodeAt(i);
  }
  return PALETA_AVATAR[soma % PALETA_AVATAR.length];
}

// Bolinha do cabeçalho - foto quando `usuario.idImagemPerfil`/`foto` vier
// preenchido (upload já existe, `25-arquivo` - é o que `SeletorFotoPerfil`
// usa), inicial do primeiro nome em maiúsculo quando não há foto.
export type TamanhoAvatar = 'sm' | 'md' | 'lg' | 'xl' | 'xxl';
export type FormaAvatar = 'circulo' | 'quadrado';

const CLASSE_TAMANHO: Record<TamanhoAvatar, string> = {
  sm: 'w-8 h-8 text-xs',
  md: 'w-9 h-9 text-sm',
  lg: 'w-14 h-14 text-xl',
  // 'xl' (10-08-2026, card de perfil largo do Minha Conta) - grande o
  // bastante pra ser o elemento visual principal de um card lateral, sem
  // exigir upload de foto de verdade pra já parecer "de gente grande"
  // (a inicial colorida já resolve isso, mesma lógica do resto do app).
  xl: 'w-24 h-24 text-4xl',
  // 'xxl' (11-08-2026, faixa de identidade do Minha Conta, estilo perfil
  // acadêmico tipo ORCID/Google Acadêmico) - 112px, o maior da escala,
  // âncora visual de uma faixa larga no topo da página.
  xxl: 'w-28 h-28 text-5xl',
};

// 'quadrado' (10-08-2026, pedido do Lucas: "o quadradinho da imagem",
// card de perfil parecido com portfólio) - rounded-2xl, não rounded-lg
// nem cantos retos: seguem o mesmo raio generoso já usado nos cartões do
// painel (cartao-formulario.jsx usa rounded-3xl), só um degrau abaixo.
// 'circulo' continua sendo o padrão em todo o resto do app (cabeçalho,
// tabelas, dropdown) - não muda nada pra quem já usa o componente.
const CLASSE_FORMA: Record<FormaAvatar, string> = {
  circulo: 'rounded-full',
  quadrado: 'rounded-2xl',
};

interface AvatarUsuarioProps {
  nome?: string | null;
  foto?: string | null;
  tamanho?: TamanhoAvatar;
  forma?: FormaAvatar;
}

export function AvatarUsuario({ nome, foto, tamanho = 'md', forma = 'circulo' }: AvatarUsuarioProps) {
  const classeTamanho = CLASSE_TAMANHO[tamanho] ?? CLASSE_TAMANHO.md;
  const classeForma = CLASSE_FORMA[forma] ?? CLASSE_FORMA.circulo;
  const nomeSeguro = nome?.trim() || '?';

  if (foto) {
    return (
      <img
        src={foto}
        alt={nomeSeguro}
        className={classeTamanho + ' ' + classeForma + ' object-cover shrink-0'}
      />
    );
  }

  return (
    <div
      className={
        classeTamanho +
        ' ' +
        classeForma +
        ' flex items-center justify-center font-bold text-white shrink-0'
      }
      style={{ backgroundColor: corPorNome(nomeSeguro) }}
      aria-hidden="true"
    >
      {nomeSeguro[0].toUpperCase()}
    </div>
  );
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type { KeyboardEvent as ReactKeyboardEvent } from 'react';
import { useNavigate } from 'react-router';
import { ROTAS_ADMIN } from '../../services/router/rotas.constants';
import { usuarioApi } from '../../services/1-usuario/api/usuario.api';
import { papelApi, permissaoApi } from '../../services/2-papel-permissao/api/papel-permissao.api';
import { configuracaoApi } from '../../services/11-configuracoes/api/configuracao.api';
import { EVENTO_ABRIR_BUSCA_GLOBAL as EVENTO_ABRIR } from './busca-global-evento';
import type { UseAuthReturn } from '../../services/3-auth/hook/use-auth';
import type { UsuarioResponse } from '../../services/1-usuario/type/usuario.type';
import type { PapelResponse, PermissaoResponse } from '../../services/2-papel-permissao/type/papel-permissao.type';
import type { ConfiguracaoResponse } from '../../services/11-configuracoes/type/configuracao.type';

interface ResultadoBusca {
  categoria: string;
  rotulo?: string;
  subtitulo?: string | null;
  caminho: string;
  icone?: string;
}

interface DadosCatalogos {
  usuarios: UsuarioResponse[];
  papeis: PapelResponse[];
  permissoes: PermissaoResponse[];
  configuracoes: ConfiguracaoResponse[];
}

// Derivado de ROTAS_ADMIN (09-08-2026), não mais uma lista à mão - era uma
// cópia manual das 4 abas que podia desalinhar (mesmo problema que
// ROTAS_ADMIN/GRUPOS_MENU_ADMIN já resolveram uma vez pro menu lateral).
// Ícone aqui é o MESMO que aparece no menu lateral (rota.icone) - pedido
// do Lucas ao ver a busca: "coloca estes exatos ícones no menu também".
const NAVEGACAO: ResultadoBusca[] = ROTAS_ADMIN.map((rota) => ({
  categoria: 'Navegação',
  rotulo: rota.rotuloMenu,
  caminho: rota.caminho,
  icone: rota.icone,
}));

// Catálogos pequenos hoje (dezenas de linhas) - busca 100% no navegador,
// não justifica endpoint de busca no backend ainda (mesmo raciocínio de
// TAMANHO_PAGINA_PADRAO em paginacao.util.ts: "não faz sentido construir
// isso contra 17 linhas de teste"). Revisar se algum catálogo crescer bem
// além disso.
const LIMITE_POR_CATEGORIA = 5;

function contem(texto: string | null | undefined, termo: string): boolean {
  return (texto ?? '').toLowerCase().includes(termo);
}

interface BuscaGlobalProps {
  auth: Pick<UseAuthReturn, 'authFetch'>;
}

// Busca global - Ctrl+K/Cmd+K (09-08-2026, pedido do Lucas depois de
// gostar da sugestão: "vamos aplicar pra eu ver como fico"). Um modal só
// que busca por nome/e-mail/chave em usuário/papel/permissão/configuração
// ao mesmo tempo, e também pula direto pras 4 abas do menu. Carrega os 4
// catálogos só na PRIMEIRA vez que abre (mesma convenção de
// LogAuditoriaPainel - não gasta requisição em quem nunca aperta Ctrl+K),
// guarda em cache pro resto da sessão.
export function BuscaGlobal({ auth }: BuscaGlobalProps) {
  const navigate = useNavigate();
  const [aberto, setAberto] = useState(false);
  const [termo, setTermo] = useState('');
  const [indiceSelecionado, setIndiceSelecionado] = useState(0);
  const [dados, setDados] = useState<DadosCatalogos | null>(null); // null = ainda não carregou
  const [carregando, setCarregando] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const carregarDados = useCallback(() => {
    if (dados || carregando) {
      return;
    }
    setCarregando(true);
    Promise.all([
      usuarioApi.listar(auth.authFetch),
      papelApi.listar(auth.authFetch),
      permissaoApi.listar(auth.authFetch),
      configuracaoApi.listar(auth.authFetch),
    ])
      .then(([usuarios, papeis, permissoes, configuracoes]) => {
        setDados({ usuarios, papeis, permissoes, configuracoes });
      })
      .catch(() => setDados({ usuarios: [], papeis: [], permissoes: [], configuracoes: [] }))
      .finally(() => setCarregando(false));
  }, [auth.authFetch, dados, carregando]);

  const abrir = useCallback(() => {
    setAberto(true);
    setTermo('');
    setIndiceSelecionado(0);
    carregarDados();
  }, [carregarDados]);

  const fechar = useCallback(() => setAberto(false), []);

  useEffect(() => {
    function aoTeclarGlobal(evento: KeyboardEvent) {
      if ((evento.ctrlKey || evento.metaKey) && evento.key.toLowerCase() === 'k') {
        evento.preventDefault();
        abrir();
      }
    }
    function aoReceberEventoAbrir() {
      abrir();
    }
    window.addEventListener('keydown', aoTeclarGlobal);
    window.addEventListener(EVENTO_ABRIR, aoReceberEventoAbrir);
    return () => {
      window.removeEventListener('keydown', aoTeclarGlobal);
      window.removeEventListener(EVENTO_ABRIR, aoReceberEventoAbrir);
    };
  }, [abrir]);

  useEffect(() => {
    if (aberto) {
      inputRef.current?.focus();
    }
  }, [aberto]);

  const resultados = useMemo(() => {
    const termoBusca = termo.trim().toLowerCase();

    if (!termoBusca) {
      return NAVEGACAO;
    }

    const lista = NAVEGACAO.filter((item) => contem(item.rotulo, termoBusca));

    if (dados) {
      lista.push(
        ...dados.usuarios
          .filter((u) => contem(u.nome, termoBusca) || contem(u.email, termoBusca))
          .slice(0, LIMITE_POR_CATEGORIA)
          .map((u) => ({
            categoria: 'Usuários',
            rotulo: u.nome,
            subtitulo: u.email,
            caminho: `/admin/usuarios/${u.idUsuario}/consultar`,
            icone: 'fa-user',
          })),
        ...dados.papeis
          .filter((p) => contem(p.nome, termoBusca))
          .slice(0, LIMITE_POR_CATEGORIA)
          .map((p) => ({
            categoria: 'Papéis',
            rotulo: p.nome,
            caminho: `/admin/papeis/${p.idPapel}/alterar`,
            icone: 'fa-user-shield',
          })),
        // Permissão não tem tela própria (catálogo só-leitura) - manda pra
        // Papéis & Permissões, onde ela aparece na matriz/listagem.
        ...dados.permissoes
          .filter((p) => contem(p.nome, termoBusca))
          .slice(0, LIMITE_POR_CATEGORIA)
          .map((p) => ({
            categoria: 'Permissões',
            rotulo: p.nome,
            caminho: '/admin/papeis',
            icone: 'fa-key',
          })),
        ...dados.configuracoes
          .filter((c) => contem(c.chave, termoBusca) || contem(c.descricao, termoBusca))
          .slice(0, LIMITE_POR_CATEGORIA)
          .map((c) => ({
            categoria: 'Parâmetros',
            rotulo: c.chave,
            subtitulo: c.descricao,
            caminho: `/admin/configuracoes/${c.idConfig}/consultar`,
            icone: 'fa-sliders',
          })),
      );
    }

    return lista;
  }, [termo, dados]);

  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => setIndiceSelecionado(0), [resultados.length, termo]);

  const irPara = useCallback(
    (item: ResultadoBusca) => {
      navigate(item.caminho);
      fechar();
    },
    [navigate, fechar],
  );

  const aoTeclarInput = (evento: ReactKeyboardEvent<HTMLInputElement>) => {
    if (evento.key === 'ArrowDown') {
      evento.preventDefault();
      setIndiceSelecionado((i) => Math.min(i + 1, resultados.length - 1));
    } else if (evento.key === 'ArrowUp') {
      evento.preventDefault();
      setIndiceSelecionado((i) => Math.max(i - 1, 0));
    } else if (evento.key === 'Enter' && resultados[indiceSelecionado]) {
      evento.preventDefault();
      irPara(resultados[indiceSelecionado]);
    } else if (evento.key === 'Escape') {
      fechar();
    }
  };

  if (!aberto) {
    return null;
  }

  const grupos: { categoria: string; itens: ResultadoBusca[] }[] = [];
  for (const item of resultados) {
    let grupo = grupos.find((g) => g.categoria === item.categoria);
    if (!grupo) {
      grupo = { categoria: item.categoria, itens: [] };
      grupos.push(grupo);
    }
    grupo.itens.push(item);
  }

  return (
    <div
      className="fixed inset-0 z-[200] flex items-start justify-center pt-24 px-4 bg-black/40"
      onClick={fechar}
    >
      <div
        className="w-full max-w-lg fundo-elevado rounded-2xl shadow-2xl border borda-forte overflow-hidden"
        onClick={(evento) => evento.stopPropagation()}
      >
        <div className="flex items-center gap-3 px-4 py-3 border-b borda-padrao">
          <i className="fa-solid fa-magnifying-glass texto-fraco"></i>
          <input
            ref={inputRef}
            type="text"
            value={termo}
            onChange={(evento) => setTermo(evento.target.value)}
            onKeyDown={aoTeclarInput}
            placeholder="Buscar usuário, papel, permissão, parâmetro..."
            className="flex-1 outline-none text-sm texto-forte bg-transparent placeholder:texto-fraco"
          />
          <kbd className="text-[10px] font-bold texto-fraco border borda-forte rounded px-1.5 py-0.5">
            Esc
          </kbd>
        </div>

        <div className="max-h-96 overflow-y-auto py-2">
          {carregando && <p className="px-4 py-3 text-sm texto-fraco">Carregando...</p>}
          {!carregando && resultados.length === 0 && (
            <p className="px-4 py-3 text-sm texto-fraco">Nada encontrado para "{termo}".</p>
          )}
          {grupos.map((grupo) => (
            <div key={grupo.categoria}>
              <div className="px-4 pt-2 pb-1 text-[11px] font-bold uppercase tracking-widest texto-fraco">
                {grupo.categoria}
              </div>
              {grupo.itens.map((item) => {
                const indice = resultados.indexOf(item);
                const selecionado = indice === indiceSelecionado;
                return (
                  <button
                    key={`${item.categoria}-${item.rotulo}-${indice}`}
                    type="button"
                    onClick={() => irPara(item)}
                    onMouseEnter={() => setIndiceSelecionado(indice)}
                    className={
                      'w-full flex items-center gap-3 px-4 py-2 text-left text-sm ' +
                      (selecionado ? 'fundo-realce' : '')
                    }
                  >
                    <i
                      className={'fa-solid ' + (item.icone ?? 'fa-circle') + ' texto-fraco w-4'}
                    ></i>
                    <span className="flex-1 min-w-0">
                      <span className="block texto-forte font-medium truncate">
                        {item.rotulo}
                      </span>
                      {item.subtitulo && (
                        <span className="block text-xs texto-fraco truncate">
                          {item.subtitulo}
                        </span>
                      )}
                    </span>
                  </button>
                );
              })}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

