import { CampoSomenteLeitura } from '../../components/crud/campo-somente-leitura';
import { CartaoFormulario } from '../../components/crud/cartao-formulario';
import { useAvisoAlteracaoNaoSalva } from '../../components/crud/use-alteracao-nao-salva';
import { CampoFicha, SecaoFicha } from '../../components/crud/ficha-consulta';
import { SeletorFotoPerfil } from '../../components/input/seletor-foto-perfil';
import { useErroToast } from '../../components/layout/use-erro-toast';
import { useToast } from '../../components/layout/use-toast';
import { formatarCpf } from '../../services/constant/utils/formatacao.util';
import { arquivoApi } from '../../services/25-arquivo/api/arquivo.api';
import { usuarioApi } from '../../services/1-usuario/api/usuario.api';
import { papelApi, usuarioPapelApi } from '../../services/2-papel-permissao/api/papel-permissao.api';
import { perfilPesquisadorApi } from '../../services/6-perfil-pesquisador/api/perfil-pesquisador.api';
import {
  ROTULO_STATUS_PESQUISADOR,
  ROTULO_TIPO_VINCULO,
  ROTULO_TITULO_ACADEMICO,
  classeBadgeStatusPesquisador,
} from '../../services/6-perfil-pesquisador/constants/status-pesquisador.constants';
import { SecaoModeracao } from './secao-moderacao';
import type { PropsPagina } from '../../services/router/pagina.type';
import type { UsuarioResponse } from '../../services/1-usuario/type/usuario.type';
import type { PapelResponse, UsuarioPapelResponse } from '../../services/2-papel-permissao/type/papel-permissao.type';
import type { PerfilPesquisadorResponse } from '../../services/6-perfil-pesquisador/type/perfil-pesquisador.type';

interface DadosAtualizarUsuario {
  nome: string;
  novaSenha?: string;
  idImagemPerfil?: number | null;
}

// Precisa bater com o hash seedado em arquivos_banco_dados/07_seed_dados.sql
// ([07-D-1]) - se alguém trocar a senha de dev do seed, troca aqui também.
// Só existe pra dar um jeito rápido de voltar a ter uma senha CONHECIDA pra
// testar login depois que a senha real de alguém foi trocada/esquecida -
// nunca em produção (ver selo <dev> no botão abaixo).
const SENHA_DEV = 'DevTcc123!';

// Segunda view do padrão "uma página por operação de CRUD" (a primeira foi
// criar-usuario.jsx) - pedido do Lucas, 02-08-2026: Alterar/Excluir saem de
// dentro da tabela (GenericTable) e viram rota própria, com todos os dados
// visíveis e um botão de confirmar/cancelar no fim, em vez de edição em
// linha misturada com a listagem.
//
// Seções via <SecaoFicha> (09-08-2026, "mesmo estilo que já usei em
// Consultar" - pedido do Lucas) - reaproveita o MESMO componente de
// ficha-consulta.jsx aqui, mesmo sendo formulário editável: o "estilo" que
// o Lucas gostou (título pequeno maiúsculo separando blocos) não é
// exclusivo de campo somente-leitura, serve pra organizar qualquer grupo
// de campos.
export function AlterarUsuario({ auth }: PropsPagina) {
  // Default '' - toda rota que renderiza esta view sempre tem :id
  // (rotas.constants.ts), mas useParams() tipa como string | undefined;
  // '' nunca acontece na prática, e se acontecesse as chamadas de API só
  // falhariam graciosamente (já tratadas pelo catch existente), não
  // travariam a tela.
  const { id = '' } = useParams();
  const navigate = useNavigate();
  const { mostrar } = useToast();
  const { erro, reportarErro, limparErro } = useErroToast();
  const [usuario, setUsuario] = useState<UsuarioResponse | null>(null);
  const [nome, setNome] = useState('');
  const [novaSenha, setNovaSenha] = useState('');
  // Foto de perfil (módulo 25-arquivo) - `avatarUrl` é o que existe HOJE
  // (busca separada, ver Promise.all abaixo). `idImagemPerfilNovo` tem 3
  // estados de propósito (25-08-2026, botão "Remover foto"): `undefined` =
  // nenhuma escolha nova ainda (mostra `avatarUrl`); um número = foto nova
  // escolhida (upload já confirmado no backend, só falta mandar esse id no
  // PATCH); `null` = pessoa pediu pra REMOVER a foto atual (manda
  // idImagemPerfil: null no PATCH). `avatarUrlNovo` acompanha o mesmo
  // estado só pra prévia (null quando removida, sem cair de volta pra
  // `avatarUrl` antiga).
  const [avatarUrl, setAvatarUrl] = useState<string | null>(null);
  const [idImagemPerfilNovo, setIdImagemPerfilNovo] = useState<number | null | undefined>(undefined);
  const [avatarUrlNovo, setAvatarUrlNovo] = useState<string | null>(null);
  // Perfil de Pesquisador (25-08-2026, mesmo padrão de consultar-usuario.jsx)
  // - `null` = não é pesquisador (upgrade nunca feito, seja pelo próprio
  // usuário ou por um papel atribuído direto pelo Admin sem o upgrade real
  // - `perfil_pesquisador` é a fonte de verdade, não o papel). Some a
  // seção inteira nesse caso, em vez de mostrar campo vazio/desabilitado
  // pra sempre.
  const [perfilPesquisador, setPerfilPesquisador] = useState<PerfilPesquisadorResponse | null>(null);
  const [carregando, setCarregando] = useState(true);
  const [enviando, setEnviando] = useState(false);
  const [redefinindoSenhaDev, setRedefinindoSenhaDev] = useState(false);
  // Papéis do usuário - pedido do Lucas (03-08-2026): "criar um usuário e
  // promover ele a um cargo, incluindo o de administrador", pela interface,
  // não digitando ID cru (o widget "Papéis de um usuário" já fazia isso,
  // mas pedindo o id_usuario na mão - aqui já se sabe de quem é).
  const [papeisAtuais, setPapeisAtuais] = useState<UsuarioPapelResponse[]>([]);
  const [catalogoPapeis, setCatalogoPapeis] = useState<PapelResponse[]>([]);
  const [idPapelParaAtribuir, setIdPapelParaAtribuir] = useState('');
  const [atribuindoPapel, setAtribuindoPapel] = useState(false);
  const [revogandoPapel, setRevogandoPapel] = useState<number | null>(null);
  const [desbloqueando, setDesbloqueando] = useState(false);

  useEffect(() => {
    Promise.all([
      usuarioApi.buscar(auth.authFetch, id),
      usuarioPapelApi.listarPorUsuario(auth.authFetch, id).catch(() => []),
      papelApi.listar(auth.authFetch),
      arquivoApi.buscarAvatarPorUsuario(id).catch(() => null),
      // 404 = não é pesquisador - mesma tolerância dos outros acima, não
      // impede o resto do formulário de carregar.
      perfilPesquisadorApi.buscar(auth.authFetch, id).catch(() => null),
    ])
      .then(([dadosUsuario, papeisDoUsuario, catalogo, avatarAtual, perfilUsuario]) => {
        setUsuario(dadosUsuario);
        setNome(dadosUsuario.nome);
        setPapeisAtuais(papeisDoUsuario);
        setCatalogoPapeis(catalogo);
        setAvatarUrl(avatarAtual?.url ?? null);
        setPerfilPesquisador(perfilUsuario);
      })
      .catch(reportarErro)
      .finally(() => setCarregando(false));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  // Só os papéis que este usuário AINDA não tem - evita tentar atribuir de
  // novo um papel que já está na lista de cima (o backend recusaria com
  // 409, mas nem oferecer a opção é mais claro que deixar tentar e falhar).
  const papeisDisponiveis = catalogoPapeis.filter(
    (papel) => !papeisAtuais.some((atual) => atual.idPapel === papel.idPapel),
  );

  // "sujo" (09-08-2026, Bloco I do prompt de uma IA) - só compara os
  // campos que o próprio <form> salva (nome/senha/foto); atribuir/revogar
  // papel já salva na hora (cada clique é sua própria requisição), não faz
  // parte do "salvar" deste formulário. `idImagemPerfilNovo !== undefined`
  // (módulo 25-arquivo) entra aqui pelo mesmo motivo de novaSenha: o
  // upload (ou a remoção) já aconteceu de verdade no bucket/backend, só
  // falta o PATCH linkar - sair da página sem salvar perderia essa escolha
  // (o arquivo fica órfão, sem problema, mas a pessoa ficaria achando que
  // salvou).
  const sujo =
    usuario !== null &&
    (nome !== usuario.nome || novaSenha !== '' || idImagemPerfilNovo !== undefined);
  useAvisoAlteracaoNaoSalva(sujo);

  const aoCancelar = () => {
    if (sujo && !window.confirm('Você tem alterações não salvas. Sair mesmo assim?')) {
      return;
    }
    navigate(-1);
  };

  const aoAtribuirPapel = async () => {
    if (!idPapelParaAtribuir) {
      return;
    }
    limparErro();
    setAtribuindoPapel(true);
    try {
      const papelEscolhido = catalogoPapeis.find(
        (papel) => papel.idPapel === Number(idPapelParaAtribuir),
      );
      // `id` vem de useParams() - SEMPRE string, mesmo quando a URL só tem
      // dígitos (ex.: "/usuarios/8/alterar" → id === "8", não 8). O corpo
      // desta requisição é validado por AtribuirPapelRequestDto com
      // `@IsInt()` de verdade (diferente da URL de baixo, em
      // aoRevogarPapel, onde o Nest converte sozinho via ParseIntPipe) -
      // sem o Number() aqui, "idUsuario" chegava como texto e a validação
      // rejeitava com "idUsuario must be an integer number".
      await usuarioPapelApi.atribuir(auth.authFetch, Number(id), Number(idPapelParaAtribuir));
      const papeisAtualizados = await usuarioPapelApi.listarPorUsuario(auth.authFetch, id);
      setPapeisAtuais(papeisAtualizados);
      setIdPapelParaAtribuir('');
      mostrar(
        'Papel atribuído com sucesso.',
        `ID: ${id} agora tem o papel "${papelEscolhido?.nome}"`,
      );
    } catch (erroRequisicao) {
      reportarErro(erroRequisicao);
    } finally {
      setAtribuindoPapel(false);
    }
  };

  // Suspender/reativar UM papel por um tempo (09-08-2026, Bloco G) - em vez
  // de remover (aoRevogarPapel, abaixo): preserva quando foi atribuído,
  // volta sozinho no prazo. `papelSuspendendoId` só controla qual badge
  // está mostrando o mini-seletor de dias, não dispara nada sozinho.
  const [papelSuspendendoId, setPapelSuspendendoId] = useState<number | null>(null);
  const [enviandoSuspensaoPapel, setEnviandoSuspensaoPapel] = useState<number | null>(null);
  const [reativandoPapel, setReativandoPapel] = useState<number | null>(null);

  const aoSuspenderPapel = async (papel: UsuarioPapelResponse, dias: number) => {
    limparErro();
    setEnviandoSuspensaoPapel(papel.idPapel);
    try {
      // Só roda dentro do clique (indireto via onClick={() =>
      // aoSuspenderPapel(papel, dias)}), nunca durante render; a regra não
      // segue a indireção da 2ª função inline pra confirmar isso sozinha.
      // eslint-disable-next-line react-hooks/purity
      const ate = new Date(Date.now() + dias * 24 * 60 * 60 * 1000).toISOString();
      await usuarioPapelApi.suspender(auth.authFetch, id, papel.idPapel, ate);
      const papeisAtualizados = await usuarioPapelApi.listarPorUsuario(auth.authFetch, id);
      setPapeisAtuais(papeisAtualizados);
      setPapelSuspendendoId(null);
      mostrar(
        'Papel suspenso com sucesso.',
        `"${papel.nomePapel}" suspenso até ${new Date(ate).toLocaleDateString('pt-BR')}`,
      );
    } catch (erroRequisicao) {
      reportarErro(erroRequisicao);
    } finally {
      setEnviandoSuspensaoPapel(null);
    }
  };

  const aoReativarPapel = async (papel: UsuarioPapelResponse) => {
    limparErro();
    setReativandoPapel(papel.idPapel);
    try {
      await usuarioPapelApi.revogarSuspensao(auth.authFetch, id, papel.idPapel);
      const papeisAtualizados = await usuarioPapelApi.listarPorUsuario(auth.authFetch, id);
      setPapeisAtuais(papeisAtualizados);
      mostrar('Papel reativado com sucesso.', `"${papel.nomePapel}" voltou a valer normalmente`);
    } catch (erroRequisicao) {
      reportarErro(erroRequisicao);
    } finally {
      setReativandoPapel(null);
    }
  };

  const aoRevogarPapel = async (papel: UsuarioPapelResponse) => {
    limparErro();
    setRevogandoPapel(papel.idPapel);
    try {
      await usuarioPapelApi.remover(auth.authFetch, id, papel.idPapel);
      const papeisAtualizados = await usuarioPapelApi.listarPorUsuario(auth.authFetch, id);
      setPapeisAtuais(papeisAtualizados);
      mostrar('Papel revogado com sucesso.', `ID: ${id} perdeu o papel "${papel.nomePapel}"`);
    } catch (erroRequisicao) {
      reportarErro(erroRequisicao);
    } finally {
      setRevogandoPapel(null);
    }
  };

  const aoSalvar = async (evento: FormEvent<HTMLFormElement>) => {
    evento.preventDefault();
    limparErro();
    setEnviando(true);
    try {
      const dados: DadosAtualizarUsuario = { nome };
      if (novaSenha) {
        dados.novaSenha = novaSenha;
      }
      if (idImagemPerfilNovo !== undefined) {
        dados.idImagemPerfil = idImagemPerfilNovo;
      }
      await usuarioApi.atualizar(auth.authFetch, id, dados);
      mostrar('Usuário alterado com sucesso.', `ID: ${id} foi alterado`);
      navigate(-1);
    } catch (erroRequisicao) {
      reportarErro(erroRequisicao);
    } finally {
      setEnviando(false);
    }
  };

  // liberar_bloqueio_login() (03_funcoes_seguranca.sql) existia no banco
  // desde sempre, mas nenhum endpoint chamava ela - achado ao investigar
  // "o que falta no painel admin" (03-08-2026, pedido do Lucas): uma
  // conta bloqueada por excesso de tentativas de login não tinha NENHUM
  // jeito de ser desbloqueada pelo painel, só direto no banco. Botão
  // sempre visível (não é recurso <dev> - é uma ação administrativa de
  // verdade); clicar numa conta que não está bloqueada é inofensivo (só
  // zera campos que já estavam zerados).
  const aoDesbloquear = async () => {
    limparErro();
    setDesbloqueando(true);
    try {
      await usuarioApi.desbloquear(auth.authFetch, id);
      mostrar('Login desbloqueado com sucesso.', `ID: ${id} pode tentar logar novamente`);
    } catch (erroRequisicao) {
      reportarErro(erroRequisicao);
    } finally {
      setDesbloqueando(false);
    }
  };

  const aoRedefinirSenhaDev = async () => {
    limparErro();
    setRedefinindoSenhaDev(true);
    try {
      await usuarioApi.atualizar(auth.authFetch, id, { novaSenha: SENHA_DEV });
      mostrar('Senha redefinida com sucesso.', `ID: ${id} teve a senha redefinida para "${SENHA_DEV}"`);
    } catch (erroRequisicao) {
      reportarErro(erroRequisicao);
    } finally {
      setRedefinindoSenhaDev(false);
    }
  };

  return (
    <CartaoFormulario
      icone="fa-user-pen"
      titulo="Alterar Usuário"
      subtitulo="Deixe a senha em branco para não alterá-la."
      largura="larga"
      rodape={
        usuario && (
          <div className="flex gap-3 max-w-sm ml-auto">
            <button type="button" onClick={aoCancelar} className="btn btn-secondary flex-1">
              Cancelar
            </button>
            <button
              type="submit"
              form="form-alterar-usuario"
              disabled={enviando || !sujo}
              className="btn btn-primary flex-1"
            >
              {enviando ? 'Salvando...' : 'Salvar'}
            </button>
          </div>
        )
      }
    >
      {carregando ? (
        <p className="p-10 text-center text-sm texto-fraco">Carregando...</p>
      ) : !usuario ? (
        <p className="p-10 text-center text-red-700 text-sm font-bold">{erro}</p>
      ) : (
        <form id="form-alterar-usuario" onSubmit={aoSalvar} className="p-6 sm:p-10">
          {erro && <p className="text-red-700 text-sm font-bold text-center mb-6">{erro}</p>}

          {/* Cabeçalho de identidade (09-08-2026, Bloco I: "a pessoa
              precisa saber QUEM está editando") - mesmo espírito do
              cabeçalho de FichaConsulta, largura cheia acima das 2
              colunas. A bolinha de inicial virou SeletorFotoPerfil
              (módulo 25-arquivo): mesmo componente base (AvatarUsuario),
              só que agora clicável - mostra a foto já cadastrada
              (avatarUrl) até a pessoa trocar, e passa a mostrar a nova
              assim que o upload confirma (avatarUrlNovo). */}
          <div className="flex items-center gap-3 pb-6 mb-6 border-b borda-padrao">
            <SeletorFotoPerfil
              authFetch={auth.authFetch}
              nome={usuario.nome}
              url={idImagemPerfilNovo === undefined ? avatarUrl : avatarUrlNovo}
              tamanho="lg"
              aoAlterar={(idArquivo, novaUrl) => {
                setIdImagemPerfilNovo(idArquivo);
                setAvatarUrlNovo(novaUrl);
              }}
            />
            <div className="min-w-0">
              <p className="font-bold texto-forte truncate">{usuario.nome}</p>
              <p className="text-xs texto-fraco truncate">{usuario.email}</p>
            </div>
          </div>

          {/* 2 colunas a partir de lg (10-08-2026, rodada de IA
              "embelezar o painel" - causa raiz era CartaoFormulario
              estreito demais, ver comentário lá). Principal (2/3): o que
              se edita. Lateral (1/3): contexto/consulta + ações
              administrativas - mesmo padrão de Stripe/Linear/Vercel pra
              tela de edição de registro. Empilha em 1 coluna abaixo de
              lg, igual sempre foi no celular. */}
          <div className="grid lg:grid-cols-3 gap-6 items-start">
            <div className="lg:col-span-2 space-y-6">
              <SecaoFicha titulo="Dados da conta">
                <div className="sm:col-span-2">
                  <label className="rotulo-campo">Nome</label>
                  <input
                    type="text"
                    value={nome}
                    onChange={(evento) => setNome(evento.target.value)}
                    required
                    className="input-padrao"
                  />
                </div>
              </SecaoFicha>

              <SecaoFicha titulo="Acesso">
                <div className="sm:col-span-2">
                  <label className="rotulo-campo">Nova senha (opcional)</label>
                  <input
                    type="password"
                    value={novaSenha}
                    onChange={(evento) => setNovaSenha(evento.target.value)}
                    className="input-padrao"
                    placeholder="••••••••"
                  />
                </div>

                <div className="sm:col-span-2 flex items-center justify-between gap-3 rounded-lg border borda-forte p-3">
                  <p className="text-xs texto-fraco">
                    Zera o contador de tentativas de login falhas e libera a conta, caso esteja
                    bloqueada temporariamente.
                  </p>
                  <button
                    type="button"
                    onClick={aoDesbloquear}
                    disabled={desbloqueando}
                    className="btn btn-secondary shrink-0"
                  >
                    {desbloqueando ? 'Desbloqueando...' : 'Desbloquear login'}
                  </button>
                </div>
              </SecaoFicha>

              {/* Perfil de Pesquisador (25-08-2026: dado real agora, módulo
                  6 existe - some inteira pra quem não é pesquisador, em vez
                  de mostrar campo vazio/desabilitado pra sempre. Corrigido
                  06-09-2026: esta tela ainda tinha a versão DEMONSTRATIVA de
                  10-08-2026, escrita antes do módulo existir - consertado
                  só aqui em Alterar, já tinha sido corrigido em Consultar.
                  Só leitura, mesmo padrão de lá - não existe endpoint do
                  Admin editar perfil de pesquisador de outra pessoa. */}
              {perfilPesquisador && (
                <SecaoFicha titulo="Perfil de Pesquisador">
                  <CampoFicha
                    rotulo="CPF"
                    valor={perfilPesquisador.cpf ? formatarCpf(perfilPesquisador.cpf) : null}
                  />
                  <CampoFicha
                    rotulo="Status"
                    valor={
                      <span className={'badge ' + classeBadgeStatusPesquisador(perfilPesquisador.statusPesquisador)}>
                        {ROTULO_STATUS_PESQUISADOR[perfilPesquisador.statusPesquisador]}
                      </span>
                    }
                  />
                  <CampoFicha
                    rotulo="Título acadêmico"
                    valor={ROTULO_TITULO_ACADEMICO[perfilPesquisador.tituloAcademico]}
                  />
                  <CampoFicha
                    rotulo="Tipo de vínculo"
                    valor={ROTULO_TIPO_VINCULO[perfilPesquisador.tipoVinculo]}
                  />
                  <CampoFicha
                    rotulo="Vínculo institucional"
                    valor={perfilPesquisador.vinculoInstitucional}
                  />
                  <CampoFicha rotulo="Score atual" valor={perfilPesquisador.scoreAtual} />
                </SecaoFicha>
              )}

              <SecaoModeracao auth={auth} idUsuario={usuario.idUsuario} />
            </div>

            <div className="space-y-6">
              {/* colunas={1} (10-08-2026, achado do Lucas: "1 2 / 3 4"
                  ficava apertado numa coluna lateral estreita, e-mail
                  comprido esbarrava na borda) - empilhado (1/2/3/4),
                  igual ele pediu. */}
              <SecaoFicha titulo="Metadados" colunas={1}>
                <CampoSomenteLeitura rotulo="id" valor={usuario.idUsuario} />
                <CampoSomenteLeitura rotulo="E-mail" valor={usuario.email} />
                <CampoSomenteLeitura
                  rotulo="E-mail verificado"
                  valor={usuario.emailVerificado ? 'Sim' : 'Não'}
                />
                <CampoSomenteLeitura
                  rotulo="Criado em"
                  valor={usuario.criadoEm && new Date(usuario.criadoEm).toLocaleDateString('pt-BR')}
                />
              </SecaoFicha>

              <SecaoFicha titulo="Papéis">
                <div className="sm:col-span-2">
                  <div className="flex flex-wrap gap-2 mb-3">
                    {papeisAtuais.length === 0 && (
                      <p className="text-xs texto-fraco">Nenhum papel atribuído ainda.</p>
                    )}
                    {papeisAtuais.map((papel) => {
                      const suspenso =
                        papel.suspensoAte && new Date(papel.suspensoAte) > new Date();
                      return (
                        <span key={papel.idPapel} className="inline-flex flex-col items-start gap-1">
                          <span
                            className={
                              'badge flex items-center gap-2 ' +
                              (suspenso ? 'fundo-aviso texto-aviso' : 'badge-neutro')
                            }
                          >
                            {papel.nomePapel}
                            {suspenso && <i className="fa-solid fa-clock text-[10px]"></i>}
                            {suspenso ? (
                              <button
                                type="button"
                                onClick={() => aoReativarPapel(papel)}
                                disabled={reativandoPapel === papel.idPapel}
                                className="font-bold hover:underline disabled:opacity-50"
                                title="Reativar agora"
                              >
                                {reativandoPapel === papel.idPapel ? '…' : 'reativar'}
                              </button>
                            ) : (
                              <>
                                <button
                                  type="button"
                                  onClick={() =>
                                    setPapelSuspendendoId((atual) =>
                                      atual === papel.idPapel ? null : papel.idPapel,
                                    )
                                  }
                                  className="texto-fraco hover-texto-forte"
                                  title={`Suspender "${papel.nomePapel}" por um tempo`}
                                >
                                  <i className="fa-solid fa-clock text-[10px]"></i>
                                </button>
                                <button
                                  type="button"
                                  onClick={() => aoRevogarPapel(papel)}
                                  disabled={revogandoPapel === papel.idPapel}
                                  className="text-red-600 font-bold hover:text-red-800 disabled:opacity-50"
                                  title={`Revogar "${papel.nomePapel}"`}
                                >
                                  ×
                                </button>
                              </>
                            )}
                          </span>
                          {papelSuspendendoId === papel.idPapel && (
                            <span className="flex gap-1 fundo-cartao border borda-forte rounded-lg p-1.5">
                              {[1, 7, 30].map((dias) => (
                                <button
                                  key={dias}
                                  type="button"
                                  onClick={() => aoSuspenderPapel(papel, dias)}
                                  disabled={enviandoSuspensaoPapel === papel.idPapel}
                                  className="text-[10px] font-bold texto-padrao hover-fundo-sutil px-1.5 py-0.5 rounded"
                                >
                                  {dias}d
                                </button>
                              ))}
                            </span>
                          )}
                        </span>
                      );
                    })}
                  </div>

                  {papeisDisponiveis.length === 0 ? (
                    // ANTES (achado do Lucas, 03-08-2026: "não consigo
                    // atribuir papel pra ninguém"): este bloco inteiro só
                    // existia `{papeisDisponiveis.length > 0 && (...)}` -
                    // quando não sobrava nenhum papel pra atribuir (ex.:
                    // catálogo ainda não carregou, ou o usuário já tem
                    // todos), o seletor E o botão simplesmente SUMIAM da
                    // tela, sem nenhuma mensagem explicando por quê -
                    // parecia "atribuir não funciona", não "não há nada pra
                    // atribuir agora". Corrigido: sempre mostra alguma
                    // coisa, nunca um vazio sem explicação.
                    <p className="text-xs texto-fraco">
                      Nenhum papel adicional disponível pra atribuir (o catálogo ainda
                      está carregando, ou este usuário já tem todos os papéis existentes).
                    </p>
                  ) : (
                    <div className="flex flex-col gap-2">
                      <select
                        value={idPapelParaAtribuir}
                        onChange={(evento) => setIdPapelParaAtribuir(evento.target.value)}
                        className="input-padrao"
                      >
                        <option value="">Selecione um papel...</option>
                        {papeisDisponiveis.map((papel) => (
                          <option key={papel.idPapel} value={papel.idPapel}>
                            {papel.nome}
                          </option>
                        ))}
                      </select>
                      <button
                        type="button"
                        onClick={aoAtribuirPapel}
                        disabled={!idPapelParaAtribuir || atribuindoPapel}
                        className="btn btn-primary"
                      >
                        {atribuindoPapel ? 'Atribuindo...' : 'Atribuir'}
                      </button>
                    </div>
                  )}
                </div>
              </SecaoFicha>

              {/* Ferramentas de desenvolvimento (10-08-2026, pedido do
                  Lucas: "tem uns botões temporários de desenvolvimento
                  dentro, e que devem continuar lá ainda") - agrupadas num
                  card próprio, marcadas com .badge-dev, pra ficar claro
                  que somem antes de qualquer apresentação/deploy real (ver
                  pendência em temp_Nest_React.md). Desbloquear login NÃO
                  entra aqui - é ação administrativa de verdade, fica em
                  "Acesso" na coluna principal. */}
              <div className="fundo-cartao border border-dashed border-purple-300 bg-purple-50 rounded-xl p-4">
                <span className="badge badge-dev">&lt;dev&gt;</span>
                <p className="text-xs texto-fraco mt-2 mb-3">
                  Redefine a senha direto pra "{SENHA_DEV}", sem digitar nada. Só pra testar
                  login.
                </p>
                <button
                  type="button"
                  onClick={aoRedefinirSenhaDev}
                  disabled={redefinindoSenhaDev}
                  className="btn btn-secondary w-full"
                >
                  {redefinindoSenhaDev ? 'Redefinindo...' : 'Redefinir senha dev'}
                </button>
              </div>
            </div>
          </div>
        </form>
      )}
    </CartaoFormulario>
  );
}

import { useEffect, useState } from 'react';
import { Link, useNavigate, useParams } from 'react-router';
import { CampoFicha, FichaConsulta, SecaoFicha } from '../../components/crud/ficha-consulta';
import { AvatarUsuario } from '../../components/layout/avatar-usuario';
import { useErroToast } from '../../components/layout/use-erro-toast';
import { arquivoApi } from '../../services/25-arquivo/api/arquivo.api';
import { usuarioPapelApi } from '../../services/2-papel-permissao/api/papel-permissao.api';
import { usuarioApi } from '../../services/1-usuario/api/usuario.api';
import { perfilPesquisadorApi } from '../../services/6-perfil-pesquisador/api/perfil-pesquisador.api';
import {
  ROTULO_STATUS_PESQUISADOR,
  ROTULO_TIPO_VINCULO,
  ROTULO_TITULO_ACADEMICO,
  classeBadgeStatusPesquisador,
} from '../../services/6-perfil-pesquisador/constants/status-pesquisador.constants';
import { formatarCpf } from '../../services/constant/utils/formatacao.util';
import type { PropsPagina } from '../../services/router/pagina.type';
import type { UsuarioResponse, UsuarioResponseLoginHistorico } from '../../services/1-usuario/type/usuario.type';
import type { UsuarioPapelResponse } from '../../services/2-papel-permissao/type/papel-permissao.type';
import type { AvatarResolvido } from '../../services/25-arquivo/type/arquivo.type';
import type { PerfilPesquisadorResponse } from '../../services/6-perfil-pesquisador/type/perfil-pesquisador.type';

interface BotaoVerFotoPerfilProps {
  url: string;
  tamanho?: string;
  badge?: boolean;
}

// Botão de olho (04-09-2026, pedido do Lucas) - abre a foto de perfil em
// outra guia, mesmo efeito de clicar com o botão direito na imagem e
// escolher "abrir em outra guia" (link direto, sem JS/window.open). Não
// existe "tamanho máximo" de verdade aqui: é a MESMA url do avatar
// pequeno do topo da ficha, já processada pelo `sharp` no upload
// (RNF-016) e redimensionada pro teto do contexto avatar (512px, ver
// PERFIL_PROCESSAMENTO_POR_CONTEXTO em 25-arquivo/arquivo.constants.ts) -
// os bytes originais enviados pelo usuário nunca são guardados.
// `tamanho` (04-09-2026, achado do Lucas: "está cinza e apagado demais")
// - texto-forte (não -fraco) desde o início, sem depender de :hover pra
// ficar legível; usado em dois lugares nesta tela (ver `avatar` da
// FichaConsulta e o campo "Foto de perfil" abaixo).
// `badge` (04-09-2026, imagem editada pelo Lucas mostrando a posição
// exata) - selo circular escuro sobreposto no canto inferior direito do
// círculo do avatar (mesmo padrão de "editar foto" do Instagram/LinkedIn),
// em vez do ícone solto flutuando mais abaixo/à direita da tentativa
// anterior. `border` na cor do CARTÃO (não uma cor fixa) cria o anelzinho
// de respiro entre o selo e a foto, e continua certo nos dois temas.
// Sem o `title` explicando "tamanho máximo" (04-09-2026, pedido do Lucas:
// "o olho de cima não precisa deste tooltip") - a explicação completa fica
// só no olho de baixo, ao lado de "Foto cadastrada".
function BotaoVerFotoPerfil({ url, tamanho = 'text-base', badge = false }: BotaoVerFotoPerfilProps) {
  if (badge) {
    return (
      <a
        href={url}
        target="_blank"
        rel="noopener noreferrer"
        aria-label="Abrir imagem em outra guia"
        title="Abrir imagem em outra guia"
        className="w-7 h-7 rounded-full flex items-center justify-center border-2 transition-opacity hover:opacity-80"
        style={{
          backgroundColor: 'var(--color-dark)',
          borderColor: 'var(--cor-fundo-cartao)',
          color: 'var(--color-white)',
        }}
      >
        <i className="fa-solid fa-eye text-xs"></i>
      </a>
    );
  }

  return (
    <a
      href={url}
      target="_blank"
      rel="noopener noreferrer"
      aria-label="Abrir imagem em outra guia"
      title='Abrir imagem em outra guia (no tamanho "máximo" - já reduzido pelo servidor, o original não é guardado)'
      className={'texto-forte hover:opacity-70 transition-opacity shrink-0 ' + tamanho}
    >
      <i className="fa-solid fa-eye"></i>
    </a>
  );
}

// "Consultar" - botão do meio entre Alterar e Excluir (GenericTable).
// Mostra TODOS os dados do usuário ligados ao banco (UsuarioResponseDto
// inteiro), em layout de ficha (08-08-2026, ver components/crud/
// ficha-consulta.jsx - não é mais uma pilha de textbox desabilitado).
export function ConsultarUsuario({ auth }: PropsPagina) {
  const { id = '' } = useParams();
  const navigate = useNavigate();
  const [usuario, setUsuario] = useState<UsuarioResponse | null>(null);
  const [papeis, setPapeis] = useState<UsuarioPapelResponse[] | null>(null);
  // Avatar (módulo 25-arquivo) - busca separada de `usuario` de propósito:
  // GET /arquivo/avatar/:idUsuario é público (não precisa de auth.authFetch),
  // e devolve { url: null } pra quem não tem foto (SIMPLIFICADO 05-09-2026 -
  // não existe mais "avatar padrão do sistema", AvatarUsuario já desenha
  // iniciais quando `url` é null). Um erro aqui não deve impedir o resto da
  // ficha de carregar - daí o .catch(() => null) igual já é feito pra
  // `papeis` logo abaixo.
  const [avatar, setAvatar] = useState<AvatarResolvido | null>(null);
  // Perfil de pesquisador (módulo 6, 25-08-2026: existe de verdade agora,
  // o aviso "ainda não implementado" que morava aqui era só um resquício
  // de antes do módulo existir). `null` = não é pesquisador (404, mesmo
  // sinal já usado pra avatar/papéis acima) - a seção inteira some nesse
  // caso, não faz sentido mostrar "não informado" pra sempre pra quem
  // nunca vai ter esse dado.
  const [perfilPesquisador, setPerfilPesquisador] = useState<PerfilPesquisadorResponse | null>(null);
  const [carregando, setCarregando] = useState(true);
  const { erro, reportarErro } = useErroToast();
  // Histórico de login (07-08-2026, pedido do Lucas: "uma setinha que
  // liste todos os últimos logins, exceto o último") - só busca quando
  // clica (mesma convenção de LogAuditoriaPainel: não vale gastar
  // requisição em quem nunca vai abrir). `null` = ainda não buscou.
  const [logins, setLogins] = useState<UsuarioResponseLoginHistorico[] | null>(null);
  const [carregandoLogins, setCarregandoLogins] = useState(false);
  const [loginsAbertos, setLoginsAbertos] = useState(false);

  useEffect(() => {
    Promise.all([
      usuarioApi.buscar(auth.authFetch, id),
      // Não existe (nem deveria existir) uma coluna "é pesquisador" em
      // usuario - isso já é decidido pelo RBAC (usuario_papel), então é
      // isso que a consulta usa, sem duplicar a informação em outro
      // lugar.
      usuarioPapelApi.listarPorUsuario(auth.authFetch, id).catch(() => []),
      arquivoApi.buscarAvatarPorUsuario(id).catch(() => null),
      // 404 = não é pesquisador, mesmo padrão de tolerância dos dois
      // acima (não impede o resto da ficha de carregar).
      perfilPesquisadorApi.buscar(auth.authFetch, id).catch(() => null),
    ])
      .then(([dadosUsuario, papeisUsuario, avatarUsuario, perfilUsuario]) => {
        setUsuario(dadosUsuario);
        setPapeis(papeisUsuario);
        setAvatar(avatarUsuario);
        setPerfilPesquisador(perfilUsuario);
      })
      .catch(reportarErro)
      .finally(() => setCarregando(false));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  const aoAlternarLogins = async () => {
    if (loginsAbertos) {
      setLoginsAbertos(false);
      return;
    }
    setLoginsAbertos(true);
    if (logins !== null) {
      return;
    }
    setCarregandoLogins(true);
    try {
      const resultado = await usuarioApi.listarLogins(auth.authFetch, id);
      setLogins(resultado);
    } catch (erroRequisicao) {
      reportarErro(erroRequisicao);
    } finally {
      setCarregandoLogins(false);
    }
  };

  // Lista vem mais recente primeiro (backend) - o [0] é o MESMO login que
  // já aparece como valor do campo "Último login em" acima, então some
  // daqui pra não duplicar (pedido do Lucas: "exceto o último").
  const loginsAnteriores = logins?.slice(1) ?? [];

  if (carregando) {
    return <p className="p-10 text-center text-sm texto-fraco">Carregando...</p>;
  }

  if (!usuario) {
    return <p className="p-10 text-center text-red-700 text-sm font-bold">{erro}</p>;
  }

  return (
    <FichaConsulta
      titulo={usuario.nome}
      subtitulo={usuario.email}
      avatar={
        // `relative`/`absolute` (04-09-2026, achado do Lucas: empilhar em
        // flex-col empurrava a FOTO pra cima, porque o bloco inteiro
        // ficava mais alto e `items-center` recentralizava tudo) - a foto
        // fica exatamente onde sempre ficou, o selo só flutua por cima,
        // sem afetar a altura/alinhamento do cabeçalho. Posição final
        // (imagem editada pelo Lucas, 04-09-2026): selo sobreposto no
        // canto inferior direito do círculo, mesmo padrão "editar foto"
        // do Instagram/LinkedIn.
        <div className="relative shrink-0">
          <AvatarUsuario nome={usuario.nome} foto={avatar?.url} tamanho="xl" />
          {avatar?.url && (
            <div className="absolute bottom-0 right-0">
              <BotaoVerFotoPerfil url={avatar.url} badge />
            </div>
          )}
        </div>
      }
      largura="larga"
      // Sem `badges` de propósito (25-08-2026, pedido da Alexia): os
      // papéis já aparecem uma vez, de verdade, na seção "Papéis" mais
      // abaixo - mostrar de novo aqui em cima, do lado de "Alterar", era
      // duplicar a mesma informação duas vezes na mesma tela.
      // Botão "Alterar" no topo (10-08-2026, item 4: "fluxo consultar→
      // alterar é o mais comum em painel admin", hoje só dava pra editar
      // voltando pra listagem primeiro).
      acaoTopo={
        <Link to={`/admin/usuarios/${usuario.idUsuario}/alterar`} className="btn btn-primary">
          <i className="fa-solid fa-pen"></i> Alterar
        </Link>
      }
      acoes={
        <button type="button" onClick={() => navigate(-1)} className="btn btn-secondary w-full">
          Voltar
        </button>
      }
    >
      {/* 2 colunas a partir de lg (10-08-2026, item 4, mesmo padrão de
          Alterar Usuário) - principal (2/3): dados de verdade da conta.
          Lateral (1/3): Papéis. "Sessões ativas" NÃO entra aqui (mesma
          decisão do Alterar Usuário - não existe endpoint do admin ver
          sessão de outra pessoa, só o histórico de login já existente
          abaixo, que já é colapsado por padrão desde sempre). */}
      <div className="grid lg:grid-cols-3 gap-6 items-start">
        <div className="lg:col-span-2 space-y-6">
          <SecaoFicha titulo="Dados da conta">
            <CampoFicha rotulo="id" valor={usuario.idUsuario} />
            <CampoFicha
              rotulo="Foto de perfil"
              // Botão de olho à ESQUERDA do texto (04-09-2026, pedido do
              // Lucas) - por isso vem dentro de `valor`, não em `acao`
              // (que sempre renderiza à direita, ver ficha-consulta.jsx).
              // Só aparece pra quem cadastrou foto de verdade (sem foto,
              // não tem nada pra ver).
              valor={
                avatar?.url ? (
                  <span className="inline-flex items-center gap-2">
                    <BotaoVerFotoPerfil url={avatar.url} />
                    Foto cadastrada
                  </span>
                ) : (
                  'Sem foto (usa iniciais)'
                )
              }
            />
            <CampoFicha
              rotulo="Criado em"
              valor={usuario.criadoEm && new Date(usuario.criadoEm).toLocaleString('pt-BR')}
            />
            <CampoFicha
              rotulo="E-mail verificado"
              valor={usuario.emailVerificado ? 'Sim' : 'Não'}
            />
          </SecaoFicha>

          <SecaoFicha titulo="Acesso">
            {/* Tirado do log de auditoria de propósito (07-08-2026, pedido
                do Lucas: login bem-sucedido lotava o log com uma linha por
                login) - mora só aqui agora, não no log. Colapsado por
                padrão desde que existe (loginsAbertos começa false). */}
            <CampoFicha
              rotulo="Último login em"
              largura="cheia"
              valor={
                usuario.ultimoLoginEm
                  ? new Date(usuario.ultimoLoginEm).toLocaleString('pt-BR')
                  : 'Nunca'
              }
              acao={
                usuario.ultimoLoginEm && (
                  <button
                    type="button"
                    onClick={aoAlternarLogins}
                    aria-label="Ver logins anteriores"
                    title="Ver logins anteriores"
                    className="texto-fraco hover-texto-forte transition-colors shrink-0"
                  >
                    <i
                      className={
                        'fa-solid fa-chevron-down transition-transform' +
                        (loginsAbertos ? ' rotate-180' : '')
                      }
                    ></i>
                  </button>
                )
              }
            >
              {loginsAbertos && (
                <div className="mt-2 rounded-lg border borda-padrao fundo-sutil p-3 text-sm max-h-64 overflow-y-auto">
                  {carregandoLogins ? (
                    <p className="texto-fraco">Carregando...</p>
                  ) : loginsAnteriores.length === 0 ? (
                    <p className="texto-fraco">Nenhum login anterior registrado.</p>
                  ) : (
                    <ul className="space-y-1">
                      {loginsAnteriores.map((login, indice) => (
                        // criado_em não é único por usuário (chave melhor
                        // não existe aqui - a resposta não traz id_sessao
                        // de propósito, é histórico de login, não uma
                        // entidade gerenciável pelo painel).
                        <li key={indice} className="texto-padrao">
                          {new Date(login.logadoEm).toLocaleString('pt-BR')}
                        </li>
                      ))}
                    </ul>
                  )}
                </div>
              )}
            </CampoFicha>
          </SecaoFicha>

          {/* Perfil de Pesquisador (25-08-2026: dado real agora, módulo 6
              existe - some inteira pra quem não é pesquisador, em vez de
              mostrar "não informado" pra sempre pra quem nunca vai ter
              esse dado). CPF vem `null` de quem não tem a permissão
              'perfil_pesquisador_visualizar_sensivel' (o backend já decide
              isso, não é uma checagem daqui). */}
          {perfilPesquisador && (
            <SecaoFicha titulo="Perfil de Pesquisador">
              <CampoFicha
                rotulo="CPF"
                valor={perfilPesquisador.cpf ? formatarCpf(perfilPesquisador.cpf) : null}
              />
              <CampoFicha
                rotulo="Status"
                valor={
                  <span className={'badge ' + classeBadgeStatusPesquisador(perfilPesquisador.statusPesquisador)}>
                    {ROTULO_STATUS_PESQUISADOR[perfilPesquisador.statusPesquisador]}
                  </span>
                }
              />
              <CampoFicha rotulo="Título acadêmico" valor={ROTULO_TITULO_ACADEMICO[perfilPesquisador.tituloAcademico]} />
              <CampoFicha rotulo="Tipo de vínculo" valor={ROTULO_TIPO_VINCULO[perfilPesquisador.tipoVinculo]} />
              <CampoFicha rotulo="Vínculo institucional" valor={perfilPesquisador.vinculoInstitucional} />
              <CampoFicha rotulo="Score atual" valor={perfilPesquisador.scoreAtual} />
            </SecaoFicha>
          )}
        </div>

        <div className="space-y-6">
          <SecaoFicha titulo="Papéis">
            <CampoFicha
              rotulo="Papéis atribuídos"
              largura="cheia"
              valor={
                papeis === null
                  ? undefined
                  : papeis.length === 0
                    ? null
                    : papeis.map((papel) => papel.nomePapel).join(', ')
              }
            />
          </SecaoFicha>
        </div>
      </div>
    </FichaConsulta>
  );
}

import { useState } from 'react';
import type { FormEvent } from 'react';
import { useNavigate } from 'react-router';
import { CartaoFormulario } from '../../components/crud/cartao-formulario';
import { SeletorFotoPerfil } from '../../components/input/seletor-foto-perfil';
import { useErroToast } from '../../components/layout/use-erro-toast';
import { useToast } from '../../components/layout/use-toast';
import { arquivoApi } from '../../services/25-arquivo/api/arquivo.api';
import { usuarioApi } from '../../services/1-usuario/api/usuario.api';
import type { PropsPagina } from '../../services/router/pagina.type';

// Primeira de um padrão que vai se repetir: view própria por operação
// (criar/alterar/consultar/excluir), não formulário embutido dentro da
// listagem - mesmo padrão do modelo de referência (hotel: Criar.tsx/
// Alterar.tsx/Consultar.tsx/Excluir.tsx, um arquivo por operação).
export function CriarUsuario({ auth }: PropsPagina) {
  const navigate = useNavigate();
  const { mostrar } = useToast();
  const { erro, reportarErro, limparErro } = useErroToast();
  const [nome, setNome] = useState('');
  const [email, setEmail] = useState('');
  const [senha, setSenha] = useState('');
  // Foto de perfil (módulo 25-arquivo) — OPCIONAL na criação. O upload
  // acontece na hora (SeletorFotoPerfil já sobe e confirma o arquivo antes
  // de devolver o id), então aqui só guardamos o id_arquivo já confirmado
  // pra mandar junto do POST /usuario quando existir. Sem foto escolhida,
  // idImagemPerfil fica null e o campo nem entra no corpo da requisição —
  // AvatarUsuario mostra iniciais com fundo colorido até a pessoa
  // cadastrar uma foto de verdade.
  const [idImagemPerfil, setIdImagemPerfil] = useState<number | null>(null);
  const [urlImagemPerfil, setUrlImagemPerfil] = useState<string | null>(null);
  const [enviando, setEnviando] = useState(false);

  // Sem usuário criado ainda, então nem "trocar" nem "remover" (lixeira do
  // SeletorFotoPerfil) têm um PATCH pra disparar a limpeza (esse caminho
  // só existe em alterar-usuario.jsx/minha-conta-page.jsx, depois que a
  // conta já existe). Sem isto, escolher uma foto, escolher outra, ou
  // clicar na lixeira, deixava a escolha anterior (já confirmada de
  // verdade no bucket) órfã pra sempre - achado do Lucas, 25-08-2026,
  // limpando o Storage manualmente. Best-effort: se a limpeza falhar,
  // não trava a experiência de criar o usuário, só sobra um objeto
  // órfão (mesma categoria de risco já aceita no resto do módulo).
  const aoAlterarFoto = (idArquivo: number | null, novaUrl: string | null) => {
    const idAnterior = idImagemPerfil;
    setIdImagemPerfil(idArquivo);
    setUrlImagemPerfil(novaUrl);
    if (idAnterior !== null) {
      arquivoApi.remover(auth.authFetch, idAnterior).catch(() => {
        console.warn(`Falha ao limpar foto de perfil não usada (id_arquivo=${idAnterior}).`);
      });
    }
  };

  const aoCriar = async (evento: FormEvent<HTMLFormElement>) => {
    evento.preventDefault();
    limparErro();
    setEnviando(true);
    try {
      const usuarioCriado = await usuarioApi.criar(auth.authFetch, {
        nome,
        email,
        senha,
        ...(idImagemPerfil !== null ? { idImagemPerfil } : {}),
      });
      mostrar(
        'Usuário cadastrado com sucesso.',
        `O novo usuário possui o ID: ${usuarioCriado.idUsuario}`,
      );
      // ERA navigate('/') (08-08-2026, achado do Lucas: depois que "/"
      // passou a redirecionar pra /admin/dashboard em vez de
      // /admin/usuarios, criar um usuário mandava pra tela errada - o
      // "sucesso" ficava esquisito, sem a pessoa criada nem aparecer).
      // navigate(-1) volta pra onde a pessoa realmente veio (a listagem de
      // Usuários), mesmo padrão já usado por alterar/excluir-usuario.jsx.
      navigate(-1);
    } catch (erroRequisicao) {
      reportarErro(erroRequisicao);
    } finally {
      setEnviando(false);
    }
  };

  return (
    <CartaoFormulario
      icone="fa-user-plus"
      titulo="Criar Usuário"
      subtitulo="Preencha os dados abaixo para cadastrar um novo usuário."
    >
      <form onSubmit={aoCriar} className="p-10 space-y-6">
        {erro && <p className="text-red-700 text-sm font-bold text-center">{erro}</p>}

        {/* Centralizado, acima dos campos de texto - é o primeiro elemento
            visual da ficha, mesmo lugar que ocupará depois em Alterar
            Usuário. authFetch aqui é do ADMIN logado (quem está criando a
            conta), não do usuário novo - faz sentido: o novo usuário ainda
            nem existe no banco no momento do upload, id_usuario_upload
            registra quem enviou o arquivo, não de quem é o perfil. */}
        <div className="flex justify-center">
          <SeletorFotoPerfil
            authFetch={auth.authFetch}
            nome={nome || 'Novo usuário'}
            url={urlImagemPerfil}
            tamanho="xl"
            aoAlterar={aoAlterarFoto}
          />
        </div>

        <div>
          <label className="rotulo-campo">
            Nome
          </label>
          <input
            type="text"
            value={nome}
            onChange={(evento) => setNome(evento.target.value)}
            required
            className="input-padrao"
            placeholder="Nome completo"
          />
        </div>

        <div>
          <label className="rotulo-campo">
            E-mail
          </label>
          <input
            type="email"
            value={email}
            onChange={(evento) => setEmail(evento.target.value)}
            required
            className="input-padrao"
            placeholder="seu@email.com"
          />
        </div>

        <div>
          <label className="rotulo-campo">
            Senha
          </label>
          <input
            type="password"
            value={senha}
            onChange={(evento) => setSenha(evento.target.value)}
            required
            className="input-padrao"
            placeholder="••••••••"
          />
        </div>

        <button
          type="submit"
          disabled={enviando}
          className="w-full bg-dark hover:bg-black text-white font-bold text-lg py-4 rounded-xl transition-all shadow-lg hover:shadow-xl mt-4 disabled:opacity-60"
        >
          {enviando ? 'Criando...' : 'Criar'}
        </button>
      </form>
    </CartaoFormulario>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router';
import { CartaoFormulario } from '../../components/crud/cartao-formulario';
import { CampoFicha, SecaoFicha } from '../../components/crud/ficha-consulta';
import { useErroToast } from '../../components/layout/use-erro-toast';
import { useToast } from '../../components/layout/use-toast';
import { usuarioApi } from '../../services/1-usuario/api/usuario.api';
import type { PropsPagina } from '../../services/router/pagina.type';
import type { UsuarioResponse } from '../../services/1-usuario/type/usuario.type';

// Terceira view do padrão "uma página por operação de CRUD" - mostra os
// dados de verdade antes de excluir (em vez do window.confirm() genérico
// que só mostrava o nome), com botão de confirmar/cancelar no fim.
export function ExcluirUsuario({ auth }: PropsPagina) {
  const { id = '' } = useParams();
  const navigate = useNavigate();
  const { mostrar } = useToast();
  const { erro, reportarErro, limparErro } = useErroToast();
  const [usuario, setUsuario] = useState<UsuarioResponse | null>(null);
  const [carregando, setCarregando] = useState(true);
  const [excluindo, setExcluindo] = useState(false);
  // Confirmação por digitação (09-08-2026, Bloco I do prompt de uma IA:
  // exclusão de USUÁRIO exige digitar o e-mail - configuração, mais abaixo
  // em excluir-configuracao.jsx, fica só com confirmação simples, é um
  // dado técnico, não a conta de uma pessoa).
  const [confirmacao, setConfirmacao] = useState('');
  const confirmado = usuario !== null && confirmacao.trim().toLowerCase() === usuario.email.toLowerCase();

  useEffect(() => {
    usuarioApi
      .buscar(auth.authFetch, id)
      .then(setUsuario)
      .catch(reportarErro)
      .finally(() => setCarregando(false));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  const aoConfirmar = async () => {
    limparErro();
    setExcluindo(true);
    try {
      await usuarioApi.remover(auth.authFetch, id);
      mostrar('Usuário excluído com sucesso.', `ID: ${id} foi excluído`);
      navigate(-1);
    } catch (erroRequisicao) {
      reportarErro(erroRequisicao);
      setExcluindo(false);
    }
  };

  return (
    <CartaoFormulario
      icone="fa-triangle-exclamation"
      titulo="Excluir Usuário"
      subtitulo="Não existe botão de desfazer no painel."
      variante="perigo"
      rodape={
        usuario && (
          <div className="flex gap-3">
            <button
              type="button"
              onClick={() => navigate(-1)}
              className="btn btn-secondary flex-1"
            >
              Cancelar
            </button>
            {/* Vermelho só aqui, no final - nunca no topo da tela, depois
                da pessoa ter lido o que vai acontecer (09-08-2026, Bloco
                I). */}
            <button
              type="button"
              onClick={aoConfirmar}
              disabled={excluindo || !confirmado}
              className="btn btn-danger flex-1"
            >
              {excluindo ? 'Excluindo...' : 'Confirmar exclusão'}
            </button>
          </div>
        )
      }
    >
      {carregando ? (
        <p className="p-10 text-center text-sm texto-fraco">Carregando...</p>
      ) : !usuario ? (
        <p className="p-10 text-center text-red-700 text-sm font-bold">{erro}</p>
      ) : (
        <div className="p-10 space-y-6">
          {erro && <p className="text-red-700 text-sm font-bold text-center">{erro}</p>}

          {/* SecaoFicha/CampoFicha (10-08-2026, rodada de IA
              "embelezar o painel", item 3: "usar FichaConsulta INTEIRA em
              modo leitura mostrando o que será excluído, em vez de repetir
              campos") - mesmos blocos que Consultar Usuário usa pro mesmo
              dado, zero componente duplicado (CampoSomenteLeitura, a
              versão antiga de "campo desabilitado", saiu daqui). */}
          <SecaoFicha titulo="O que será excluído">
            <CampoFicha rotulo="id" valor={usuario.idUsuario} />
            <CampoFicha rotulo="Nome" valor={usuario.nome} />
            <CampoFicha rotulo="E-mail" valor={usuario.email} largura="cheia" />
            <CampoFicha
              rotulo="E-mail verificado"
              valor={usuario.emailVerificado ? 'Sim' : 'Não'}
            />
          </SecaoFicha>

          {/* Consequência real (09-08-2026, Bloco I: explicar o que
              acontece de verdade, não só "não pode ser desfeita") - é
              exclusão LÓGICA (usuario.deletado = TRUE via
              excluir_conta_usuario(), 03_funcoes_seguranca.sql [03-O]):
              nada é apagado do banco, só marcado e escondido. */}
          <div className="rounded-lg border borda-forte fundo-aviso p-4 text-sm texto-aviso">
            <p className="font-bold mb-1">
              <i className="fa-solid fa-circle-info mr-1"></i> O que acontece de verdade
            </p>
            <p>
              A conta é marcada como excluída (exclusão lógica), não apagada do banco: o login
              deixa de funcionar e o perfil some do público na hora, mas o registro continua
              existindo pra auditoria e conformidade com a LGPD. Não existe um botão de
              "restaurar" no painel - reverter isso hoje exige acesso direto ao banco.
            </p>
          </div>

          <div>
            <label className="rotulo-campo">
              Digite o e-mail "{usuario.email}" pra confirmar
            </label>
            <input
              type="text"
              value={confirmacao}
              onChange={(evento) => setConfirmacao(evento.target.value)}
              className="input-padrao"
              placeholder={usuario.email}
              autoComplete="off"
            />
          </div>
        </div>
      )}
    </CartaoFormulario>
  );
}

import { useEffect, useState } from 'react';
import { SecaoFicha } from '../../components/crud/ficha-consulta';
import { useErroToast } from '../../components/layout/use-erro-toast';
import { useToast } from '../../components/layout/use-toast';
import { usuarioApi } from '../../services/1-usuario/api/usuario.api';
import { useConfiguracoes } from '../../services/11-configuracoes/hook/use-configuracoes';
import type { UseAuthReturn } from '../../services/3-auth/hook/use-auth';
import type { UsuarioResponseSuspend } from '../../services/1-usuario/type/usuario.type';

interface SecaoModeracaoProps {
  auth: Pick<UseAuthReturn, 'authFetch'>;
  idUsuario: number | string;
}

// Moderação - suspender/revogar CONTA (09-08-2026, Bloco G do prompt do
// uma IA) - dentro de Alterar Usuário porque é ação sobre a MESMA
// conta que a tela já edita, não uma tela própria. Opções de prazo vêm de
// `configuracoes.suspensao_usuario_opcoes_dias` (nada fixo no código) +
// campo livre pra qualquer outro número de dias.
export function SecaoModeracao({ auth, idUsuario }: SecaoModeracaoProps) {
  const { mostrar } = useToast();
  const { erro, reportarErro, limparErro } = useErroToast();
  const { obterConfiguracao } = useConfiguracoes();
  // `obterConfiguracao` devolve `string | number | boolean | null` (a
  // config guarda tipos heterogêneos) - narrow explícito antes de
  // `.split`, mesmo default ('1,3,7,30') preservado como padrão de
  // verdade se o valor guardado não vier string por algum motivo.
  const valorOpcoesDias = obterConfiguracao('suspensao_usuario_opcoes_dias', '1,3,7,30');
  const opcoesDias = (typeof valorOpcoesDias === 'string' ? valorOpcoesDias : '1,3,7,30')
    .split(',')
    .map((s) => Number(s.trim()))
    .filter((n) => Number.isFinite(n) && n > 0);

  const [suspensao, setSuspensao] = useState<UsuarioResponseSuspend | null>(null);
  const [dias, setDias] = useState('');
  const [motivo, setMotivo] = useState('');
  const [enviando, setEnviando] = useState(false);

  const carregar = () => {
    usuarioApi
      .buscarSuspensao(auth.authFetch, idUsuario)
      .then(setSuspensao)
      .catch(() => setSuspensao(null));
  };
  useEffect(carregar, [auth.authFetch, idUsuario]);

  // Capturado numa const local (não `suspensao?.suspensoAte` repetido) pro
  // narrowing de "não é null" sobreviver até o JSX renderizado mais abaixo
  // - acessar a mesma propriedade de novo lá não herdaria a checagem feita
  // aqui.
  const suspensoAte = suspensao?.suspensoAte ?? null;
  const suspensoAgora = suspensoAte !== null && new Date(suspensoAte) > new Date();

  const aoSuspender = async () => {
    limparErro();
    const diasNumero = Number(dias);
    if (!diasNumero || diasNumero <= 0) {
      return;
    }
    setEnviando(true);
    try {
      const ate = new Date(Date.now() + diasNumero * 24 * 60 * 60 * 1000).toISOString();
      await usuarioApi.suspender(auth.authFetch, idUsuario, ate, motivo);
      mostrar('Usuário suspenso com sucesso.', `Até ${new Date(ate).toLocaleString('pt-BR')}`);
      setDias('');
      setMotivo('');
      carregar();
    } catch (erroRequisicao) {
      reportarErro(erroRequisicao);
    } finally {
      setEnviando(false);
    }
  };

  const aoRevogar = async () => {
    limparErro();
    setEnviando(true);
    try {
      await usuarioApi.revogarSuspensao(auth.authFetch, idUsuario);
      mostrar('Suspensão revogada com sucesso.');
      carregar();
    } catch (erroRequisicao) {
      reportarErro(erroRequisicao);
    } finally {
      setEnviando(false);
    }
  };

  return (
    <SecaoFicha titulo="Moderação">
      <div className="sm:col-span-2 space-y-3">
        {erro && <p className="text-xs texto-erro font-bold">{erro}</p>}

        {suspensoAgora ? (
          <div className="rounded-lg border borda-forte fundo-erro p-4">
            <p className="text-sm font-bold texto-erro">
              Suspenso até {suspensoAte && new Date(suspensoAte).toLocaleString('pt-BR')}
            </p>
            <p className="text-xs texto-erro mt-1">Motivo: {suspensao?.motivoSuspensao}</p>
            <button
              type="button"
              onClick={aoRevogar}
              disabled={enviando}
              className="btn btn-secondary mt-3"
            >
              {enviando ? 'Revogando...' : 'Revogar suspensão'}
            </button>
          </div>
        ) : (
          <div className="rounded-lg border borda-padrao p-4 space-y-3">
            <p className="text-xs texto-fraco">
              Suspender bloqueia o login desta conta pelo prazo escolhido, com motivo
              obrigatório (fica visível pra quem tentar entrar).
            </p>
            <div className="flex flex-wrap gap-2 items-center">
              {opcoesDias.map((d) => (
                <button
                  key={d}
                  type="button"
                  onClick={() => setDias(String(d))}
                  className={
                    'px-3 py-1.5 rounded-lg text-xs font-bold border ' +
                    (dias === String(d)
                      ? 'bg-primary text-white border-primary'
                      : 'texto-padrao borda-forte hover-fundo-sutil')
                  }
                >
                  {d} {d === 1 ? 'dia' : 'dias'}
                </button>
              ))}
              <input
                type="number"
                min="1"
                placeholder="outro (dias)"
                value={dias}
                onChange={(evento) => setDias(evento.target.value)}
                className="input-padrao w-28 py-1.5"
              />
            </div>
            <textarea
              placeholder="Motivo da suspensão (obrigatório)"
              value={motivo}
              onChange={(evento) => setMotivo(evento.target.value)}
              className="input-padrao"
              rows={2}
            />
            <button
              type="button"
              onClick={aoSuspender}
              disabled={!dias || !motivo.trim() || enviando}
              className="btn btn-danger"
            >
              {enviando ? 'Suspendendo...' : 'Suspender usuário'}
            </button>
          </div>
        )}
      </div>
    </SecaoFicha>
  );
}

import { useEffect, useState } from 'react';
import type { FormEvent } from 'react';
import { useNavigate, useParams } from 'react-router';
import { CartaoFormulario } from '../../components/crud/cartao-formulario';
import { useAvisoAlteracaoNaoSalva } from '../../components/crud/use-alteracao-nao-salva';
import { SecaoFicha } from '../../components/crud/ficha-consulta';
import { useErroToast } from '../../components/layout/use-erro-toast';
import { useToast } from '../../components/layout/use-toast';
import { motivoDenunciaApi } from '../../services/10-motivo-denuncia/api/motivo-denuncia.api';
import { ehTipoMotivoDenuncia } from '../../services/10-motivo-denuncia/constants/motivo-denuncia.constants';
import type { PropsPagina } from '../../services/router/pagina.type';
import type { MotivoDenunciaResponse, TipoMotivoDenuncia } from '../../services/10-motivo-denuncia/type/motivo-denuncia.type';

// `tipo` É editável aqui: não existe trigger no banco que trave a troca
// depois de criado (ver comentário completo em
// atualizar-motivo-denuncia.request.dto.ts, no backend). `descricao`
// também é editável - desde 18-08-2026 (remoção de `codigo`) é o único
// identificador do motivo, então precisa continuar não vazia.
export function AlterarMotivoDenuncia({ auth }: PropsPagina) {
  const { id = '' } = useParams();
  const navigate = useNavigate();
  const { mostrar } = useToast();
  const { erro, reportarErro, limparErro } = useErroToast();
  const [motivo, setMotivo] = useState<MotivoDenunciaResponse | null>(null);
  const [descricao, setDescricao] = useState('');
  const [tipo, setTipo] = useState<TipoMotivoDenuncia | ''>('');
  const [ativo, setAtivo] = useState(true);
  const [carregando, setCarregando] = useState(true);
  const [enviando, setEnviando] = useState(false);

  useEffect(() => {
    motivoDenunciaApi
      .buscar(auth.authFetch, id)
      .then((dados) => {
        setMotivo(dados);
        setDescricao(dados.descricao ?? '');
        setTipo(dados.tipo);
        setAtivo(dados.ativo);
      })
      .catch(reportarErro)
      .finally(() => setCarregando(false));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  const sujo =
    motivo !== null &&
    (descricao !== (motivo.descricao ?? '') || tipo !== motivo.tipo || ativo !== motivo.ativo);
  useAvisoAlteracaoNaoSalva(sujo);

  const aoCancelar = () => {
    if (sujo && !window.confirm('Você tem alterações não salvas. Sair mesmo assim?')) {
      return;
    }
    navigate(-1);
  };

  const aoSalvar = async (evento: FormEvent<HTMLFormElement>) => {
    evento.preventDefault();
    if (tipo === '') return;
    limparErro();
    setEnviando(true);
    try {
      await motivoDenunciaApi.atualizar(auth.authFetch, id, {
        descricao,
        tipo,
        ativo,
      });
      mostrar('Motivo de denúncia alterado com sucesso.', `ID: ${id} foi alterado`);
      navigate(-1);
    } catch (erroRequisicao) {
      reportarErro(erroRequisicao);
    } finally {
      setEnviando(false);
    }
  };

  return (
    <CartaoFormulario
      icone="fa-flag"
      titulo="Alterar Motivo de Denúncia"
      rodape={
        motivo && (
          <div className="flex gap-3">
            <button type="button" onClick={aoCancelar} className="btn btn-secondary flex-1">
              Cancelar
            </button>
            <button
              type="submit"
              form="form-alterar-motivo-denuncia"
              disabled={enviando || !sujo || tipo === '' || descricao.trim() === ''}
              className="btn btn-primary flex-1"
            >
              {enviando ? 'Salvando...' : 'Salvar'}
            </button>
          </div>
        )
      }
    >
      {carregando ? (
        <p className="p-10 text-center text-sm texto-fraco">Carregando...</p>
      ) : !motivo ? (
        <p className="p-10 text-center text-red-700 text-sm font-bold">{erro}</p>
      ) : (
        <form id="form-alterar-motivo-denuncia" onSubmit={aoSalvar} className="p-10 space-y-6">
          {erro && <p className="text-red-700 text-sm font-bold text-center">{erro}</p>}

          <div className="flex items-center gap-3 pb-4 border-b borda-padrao">
            <div className="w-11 h-11 rounded-full bg-primary text-white flex items-center justify-center shrink-0">
              <i className="fa-solid fa-flag"></i>
            </div>
            <div className="min-w-0">
              <p className="font-bold texto-forte truncate text-sm">{motivo.descricao}</p>
              <p className="text-xs texto-fraco">Motivo de denúncia #{motivo.idMotivo}</p>
            </div>
          </div>

          <SecaoFicha titulo="Editar">
            <div className="sm:col-span-2">
              <label className="rotulo-campo">Tipo</label>
              <select
                value={tipo}
                onChange={(evento) => {
                  if (ehTipoMotivoDenuncia(evento.target.value)) {
                    setTipo(evento.target.value);
                  }
                }}
                required
                className="input-padrao"
              >
                <option value="campanha">Campanha</option>
                <option value="perfil">Perfil</option>
              </select>
              <p className="text-xs texto-fraco mt-1">
                Alterar isto muda em qual tela de denúncia este motivo aparece daqui pra frente -
                denúncias antigas que já usaram este motivo não são afetadas retroativamente.
              </p>
            </div>

            <div className="sm:col-span-2">
              <label className="rotulo-campo">Descrição</label>
              <input
                type="text"
                value={descricao}
                onChange={(evento) => setDescricao(evento.target.value)}
                required
                maxLength={255}
                className="input-padrao"
              />
            </div>

            <label className="sm:col-span-2 flex items-center gap-2 text-sm font-semibold texto-padrao">
              <input
                type="checkbox"
                checked={ativo}
                onChange={(evento) => setAtivo(evento.target.checked)}
              />
              Ativo
            </label>
          </SecaoFicha>
        </form>
      )}
    </CartaoFormulario>
  );
}

