import { useState } from 'react';
import type { FormEvent } from 'react';
import { useNavigate } from 'react-router';
import { CartaoFormulario } from '../../components/crud/cartao-formulario';
import { useErroToast } from '../../components/layout/use-erro-toast';
import { useToast } from '../../components/layout/use-toast';
import { configuracaoApi } from '../../services/11-configuracoes/api/configuracao.api';
import type { PropsPagina } from '../../services/router/pagina.type';
import type { TipoConfiguracao } from '../../services/11-configuracoes/type/configuracao.type';

// Convenção de chave (10-08-2026, rodada de IA "embelezar o painel",
// item 6: "o Lucas não entendeu como usar") - minúsculas, número e
// underscore, sem espaço nem acento. Mesma convenção que TODAS as chaves
// já cadastradas no seed seguem (07_seed_dados.sql), só nunca tinha virado
// validação de verdade no front - antes aceitava qualquer texto livre.
const REGEX_CHAVE_VALIDA = /^[a-z0-9_]+$/;

// `<select>` só tem essas 4 opções fixas - guarda de tipo em vez de `as`
// pra provar ao TypeScript que o valor cru do DOM (sempre `string`) é um
// `TipoConfiguracao` de verdade antes de guardar no estado.
function ehTipoConfiguracao(valor: string): valor is TipoConfiguracao {
  return valor === 'decimal' || valor === 'inteiro' || valor === 'texto' || valor === 'booleano';
}

// Antes era um formulário embutido no fim da tabela de Configurações
// (GenericTable). Virou view própria (pedido do Lucas, 02-08-2026),
// seguindo o mesmo padrão de views/1-usuario/criar-usuario.jsx.
export function CriarConfiguracao({ auth }: PropsPagina) {
  const navigate = useNavigate();
  const { mostrar } = useToast();
  const { erro, reportarErro, limparErro } = useErroToast();
  const [chave, setChave] = useState('');
  const [valor, setValor] = useState('');
  const [tipo, setTipo] = useState<TipoConfiguracao | ''>('');
  const [descricao, setDescricao] = useState('');
  const [enviando, setEnviando] = useState(false);

  // Só valida depois que a pessoa digitou alguma coisa - chave vazia não
  // é "inválida", é só "ainda não preenchida" (o `required` do <input> já
  // cuida de bloquear o envio vazio, não precisa duplicar essa mensagem).
  const chaveInvalida = chave.length > 0 && !REGEX_CHAVE_VALIDA.test(chave);

  const aoCriar = async (evento: FormEvent<HTMLFormElement>) => {
    evento.preventDefault();
    if (tipo === '') return;
    limparErro();
    setEnviando(true);
    try {
      // Decimal aceita vírgula na digitação (convenção pt-BR, pedido do
      // Lucas) - convertida pra ponto só aqui, na hora de enviar: o banco
      // lê essa string com `::DECIMAL` (config_numero(), 03_funcoes_
      // seguranca.sql), que exige notação SQL padrão (ponto), não aceita
      // vírgula.
      const valorParaEnviar = tipo === 'decimal' ? valor.replace(',', '.') : valor;
      const configuracaoCriada = await configuracaoApi.criar(auth.authFetch, {
        chave,
        valor: valorParaEnviar,
        tipo,
        descricao,
      });
      mostrar(
        'Parâmetro cadastrado com sucesso.',
        `O novo parâmetro possui o ID: ${configuracaoCriada.idConfig}`,
      );
      navigate(-1);
    } catch (erroRequisicao) {
      reportarErro(erroRequisicao);
    } finally {
      setEnviando(false);
    }
  };

  return (
    <CartaoFormulario
      icone="fa-gear"
      titulo="Criar Parâmetro"
      subtitulo="Preencha os dados abaixo para cadastrar um novo parâmetro."
    >
      <form onSubmit={aoCriar} className="p-10 space-y-6">
        {erro && <p className="text-red-700 text-sm font-bold text-center">{erro}</p>}

        {/* Aviso honesto (10-08-2026, item 6) - a confusão do Lucas era
            achar que criar uma chave pelo painel já faz o sistema passar a
            usá-la. Não faz: só tem efeito se algum código já consultar
            essa chave específica (`obterConfiguracao('chave', padrao)`
            ou `config_numero()`). */}
        <div className="flex items-start gap-2 rounded-lg fundo-info texto-info p-3">
          <i className="fa-solid fa-circle-info mt-0.5 shrink-0"></i>
          <p className="text-xs">
            Criar uma chave nova aqui não faz o sistema passar a usá-la sozinho - só tem
            efeito se algum código já consultar essa chave específica. Serve pra ajustar um
            valor que já é lido de algum lugar (taxa, limite, prazo), não pra criar
            comportamento novo.
          </p>
        </div>

        <div>
          <label className="rotulo-campo">Chave</label>
          <input
            type="text"
            value={chave}
            onChange={(evento) => setChave(evento.target.value)}
            required
            placeholder="ex.: limite_campanhas_simultaneas"
            aria-invalid={chaveInvalida}
            className={'input-padrao font-mono' + (chaveInvalida ? ' border-red-500' : '')}
          />
          {chaveInvalida ? (
            <p className="text-xs text-red-600 font-semibold mt-1">
              Só letras minúsculas, números e underscore - sem espaço, maiúscula ou acento.
            </p>
          ) : (
            <p className="text-xs texto-fraco mt-1">
              Minúsculas, números e underscore (_), sem espaço nem acento.
            </p>
          )}
        </div>

        <div>
          <label className="rotulo-campo">Tipo</label>
          <select
            value={tipo}
            onChange={(evento) => {
              if (ehTipoConfiguracao(evento.target.value)) {
                setTipo(evento.target.value);
                setValor('');
              }
            }}
            required
            className="input-padrao"
          >
            <option value="" disabled>
              Selecione...
            </option>
            <option value="decimal">Decimal</option>
            <option value="inteiro">Inteiro</option>
            <option value="texto">Texto</option>
            <option value="booleano">Booleano</option>
          </select>
        </div>

        {/* Campo Valor muda de cara conforme o Tipo (10-08-2026, item 6:
            "remove a sensação de 'não sei o que digitar'") - booleano vira
            toggle (nunca deixa digitar "sim"/"verdadeiro"/"1" por engano),
            inteiro vira number sem casa decimal, decimal aceita vírgula
            (convertida pra ponto só no envio, ver aoCriar). Sem tipo
            escolhido ainda, fica desabilitado - não faz sentido digitar
            um valor sem saber que formato ele deveria ter. */}
        <div>
          <label className="rotulo-campo">Valor</label>
          {tipo === 'booleano' ? (
            <button
              type="button"
              role="switch"
              aria-checked={valor === 'true'}
              onClick={() => setValor(valor === 'true' ? 'false' : 'true')}
              className={
                'w-14 h-8 rounded-full relative transition-colors shrink-0 ' +
                (valor === 'true' ? 'bg-primary' : 'fundo-sutil border borda-forte')
              }
            >
              <span
                className={
                  'absolute top-1 w-6 h-6 rounded-full bg-white shadow transition-transform ' +
                  (valor === 'true' ? 'translate-x-7' : 'translate-x-1')
                }
              ></span>
            </button>
          ) : tipo === 'inteiro' ? (
            <input
              type="number"
              step="1"
              value={valor}
              onChange={(evento) => setValor(evento.target.value)}
              placeholder="ex.: 5"
              className="input-padrao"
            />
          ) : tipo === 'decimal' ? (
            <>
              <input
                type="text"
                inputMode="decimal"
                value={valor}
                onChange={(evento) => setValor(evento.target.value)}
                placeholder="ex.: 12,5"
                className="input-padrao"
              />
              <p className="text-xs texto-fraco mt-1">Use vírgula como separador decimal.</p>
            </>
          ) : (
            <input
              type="text"
              value={valor}
              onChange={(evento) => setValor(evento.target.value)}
              disabled={tipo === ''}
              placeholder={tipo === '' ? 'Escolha o tipo primeiro' : undefined}
              className="input-padrao disabled:opacity-60 disabled:cursor-not-allowed"
            />
          )}
        </div>

        <div>
          <label className="rotulo-campo">Descrição</label>
          <input
            type="text"
            value={descricao}
            onChange={(evento) => setDescricao(evento.target.value)}
            className="input-padrao"
          />
        </div>

        <div className="flex gap-3 pt-2">
          <button
            type="button"
            onClick={() => navigate(-1)}
            className="btn btn-secondary flex-1"
          >
            Cancelar
          </button>
          <button
            type="submit"
            disabled={enviando || chaveInvalida}
            className="btn btn-primary flex-1"
          >
            {enviando ? 'Criando...' : 'Criar'}
          </button>
        </div>
      </form>
    </CartaoFormulario>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router';
import { CartaoFormulario } from '../../components/crud/cartao-formulario';
import { CampoFicha, SecaoFicha } from '../../components/crud/ficha-consulta';
import { useErroToast } from '../../components/layout/use-erro-toast';
import { useToast } from '../../components/layout/use-toast';
import { configuracaoApi } from '../../services/11-configuracoes/api/configuracao.api';
import type { PropsPagina } from '../../services/router/pagina.type';
import type { ConfiguracaoResponse } from '../../services/11-configuracoes/type/configuracao.type';

export function ExcluirConfiguracao({ auth }: PropsPagina) {
  const { id = '' } = useParams();
  const navigate = useNavigate();
  const { mostrar } = useToast();
  const { erro, reportarErro, limparErro } = useErroToast();
  const [configuracao, setConfiguracao] = useState<ConfiguracaoResponse | null>(null);
  const [carregando, setCarregando] = useState(true);
  const [excluindo, setExcluindo] = useState(false);

  useEffect(() => {
    configuracaoApi
      .buscar(auth.authFetch, id)
      .then(setConfiguracao)
      .catch(reportarErro)
      .finally(() => setCarregando(false));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  const aoConfirmar = async () => {
    limparErro();
    setExcluindo(true);
    try {
      await configuracaoApi.remover(auth.authFetch, id);
      mostrar('Parâmetro excluído com sucesso.', `ID: ${id} foi excluído`);
      navigate(-1);
    } catch (erroRequisicao) {
      reportarErro(erroRequisicao);
      setExcluindo(false);
    }
  };

  return (
    <CartaoFormulario
      icone="fa-triangle-exclamation"
      titulo="Excluir Parâmetro"
      subtitulo="Esta ação não pode ser desfeita."
      variante="perigo"
      rodape={
        configuracao && (
          <div className="flex gap-3">
            <button
              type="button"
              onClick={() => navigate(-1)}
              className="btn btn-secondary flex-1"
            >
              Cancelar
            </button>
            <button
              type="button"
              onClick={aoConfirmar}
              disabled={excluindo}
              className="btn btn-danger flex-1"
            >
              {excluindo ? 'Excluindo...' : 'Confirmar exclusão'}
            </button>
          </div>
        )
      }
    >
      {carregando ? (
        <p className="p-10 text-center text-sm texto-fraco">Carregando...</p>
      ) : !configuracao ? (
        <p className="p-10 text-center text-red-700 text-sm font-bold">{erro}</p>
      ) : (
        <div className="p-10 space-y-6">
          {erro && <p className="text-red-700 text-sm font-bold text-center">{erro}</p>}

          {/* SecaoFicha/CampoFicha (10-08-2026, mesma rodada do item 3 em
              Excluir Usuário) - mesmos blocos que Consultar usa, zero
              componente duplicado. */}
          <SecaoFicha titulo="O que será excluído">
            <CampoFicha rotulo="Chave" valor={configuracao.chave} largura="cheia" />
            <CampoFicha rotulo="Valor" valor={configuracao.valor} />
            <CampoFicha rotulo="Tipo" valor={configuracao.tipo} />
            <CampoFicha rotulo="Ativo" valor={configuracao.ativo ? 'Sim' : 'Não'} />
            <CampoFicha rotulo="Descrição" valor={configuracao.descricao} largura="cheia" />
          </SecaoFicha>

          {/* Diferente de Excluir Usuário: configuração não tem exclusão
              lógica (sem coluna `deletado`) - remover aqui é DELETE de
              verdade na tabela `configuracoes` (09-08-2026, Bloco I).
              Confirmação simples (não por digitação) porque não é a conta
              de uma pessoa, mas o aviso precisa ser honesto sobre a
              diferença. */}
          <div className="rounded-lg border borda-forte fundo-erro p-4 text-sm texto-erro">
            <p className="font-bold mb-1">
              <i className="fa-solid fa-circle-info mr-1"></i> O que acontece de verdade
            </p>
            <p>
              Diferente de excluir um usuário, esta linha some do banco pra sempre - não é
              exclusão lógica. Se algum código ainda ler a chave "{configuracao.chave}", ele
              vai passar a receber o valor padrão dele (ou dar erro, dependendo de como foi
              escrito). Confira se ela não está mais em uso antes de confirmar.
            </p>
          </div>
        </div>
      )}
    </CartaoFormulario>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router';
import { CampoFicha, FichaConsulta, SecaoFicha } from '../../components/crud/ficha-consulta';
import { useErroToast } from '../../components/layout/use-erro-toast';
import { campanhaApi } from '../../services/12-campanha/api/campanha.api';
import {
  ROTULO_STATUS_CAMPANHA,
  classeBadgeStatusCampanha,
} from '../../services/12-campanha/constants/status-campanha.constants';
import { areaConhecimentoApi } from '../../services/8-area-conhecimento/api/area-conhecimento.api';
import { usuarioApi } from '../../services/1-usuario/api/usuario.api';
import type { PropsPagina } from '../../services/router/pagina.type';
import type { CampanhaResponse } from '../../services/12-campanha/type/campanha.type';

function formatarReais(valor: number | null): string {
  return Number(valor ?? 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
}

function formatarData(iso: string | null): string {
  return iso ? new Date(iso).toLocaleString('pt-BR') : 'Não definida';
}

export function ConsultarCampanha({ auth }: PropsPagina) {
  const { id = '' } = useParams();
  const navigate = useNavigate();
  const [campanha, setCampanha] = useState<CampanhaResponse | null>(null);
  const [nomeDono, setNomeDono] = useState<string | null>(null);
  const [nomeArea, setNomeArea] = useState<string | null>(null);
  const [carregando, setCarregando] = useState(true);
  const { erro, reportarErro } = useErroToast();

  useEffect(() => {
    campanhaApi
      .buscar(auth.authFetch, id)
      .then((dados) => {
        setCampanha(dados);
        // Nome de dono/área resolvidos à parte (não vêm no
        // CampanhaResponse, só os ids) - mesmo raciocínio de junção
        // client-side de listar-campanhas.jsx, só que aqui é 1 registro
        // de cada em vez do catálogo inteiro.
        usuarioApi.buscar(auth.authFetch, dados.idUsuario).then((u) => setNomeDono(u.nome)).catch(() => {});
        areaConhecimentoApi.buscar(auth.authFetch, dados.idAreaConhecimento).then((a) => setNomeArea(a.nome)).catch(() => {});
      })
      .catch(reportarErro)
      .finally(() => setCarregando(false));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  if (carregando) {
    return <p className="p-10 text-center text-sm texto-fraco">Carregando...</p>;
  }

  if (!campanha) {
    return <p className="p-10 text-center text-red-700 text-sm font-bold">{erro}</p>;
  }

  return (
    <FichaConsulta
      titulo={campanha.titulo}
      subtitulo={nomeDono ? `Pesquisador: ${nomeDono}` : undefined}
      largura="larga"
      badges={[
        <span key="status" className={`badge ${classeBadgeStatusCampanha(campanha.status)}`}>
          {ROTULO_STATUS_CAMPANHA[campanha.status] ?? campanha.status}
        </span>,
        <span key="modelo" className="badge badge-neutro">
          {campanha.modelo}
        </span>,
      ]}
      acoes={
        <button type="button" onClick={() => navigate(-1)} className="btn btn-secondary w-full">
          Voltar
        </button>
      }
    >
      <div className="grid lg:grid-cols-3 gap-6 items-start">
        <div className="lg:col-span-2 space-y-6">
          <SecaoFicha titulo="Dados">
            <CampoFicha rotulo="id" valor={campanha.idCampanha} />
            <CampoFicha rotulo="Área do conhecimento" valor={nomeArea ?? `#${campanha.idAreaConhecimento}`} />
            <CampoFicha rotulo="Descrição" valor={campanha.descricao} largura="cheia" />
            <CampoFicha rotulo="Vídeo de apresentação" valor={campanha.videoApresentacaoUrl} largura="cheia" />
          </SecaoFicha>

          <SecaoFicha titulo="Datas">
            <CampoFicha rotulo="Início" valor={formatarData(campanha.dataInicio)} />
            <CampoFicha rotulo="Fim (previsto)" valor={formatarData(campanha.dataFim)} />
            <CampoFicha rotulo="Criada em" valor={formatarData(campanha.criadoEm)} />
            <CampoFicha rotulo="Aprovada em" valor={formatarData(campanha.aprovadoEm)} />
            <CampoFicha rotulo="Encerrada em" valor={formatarData(campanha.encerradoEm)} />
          </SecaoFicha>
        </div>

        <div className="space-y-6">
          <SecaoFicha titulo="Financeiro">
            <CampoFicha rotulo="Meta" valor={formatarReais(campanha.metaFinanceira)} />
            <CampoFicha rotulo="Arrecadado" valor={formatarReais(campanha.valorBrutoArrecadado)} />
            <CampoFicha
              rotulo="Taxa da plataforma"
              valor={campanha.taxaPlataforma === null ? 'Ainda não carimbada (não aprovada)' : `${campanha.taxaPlataforma}%`}
            />
          </SecaoFicha>
        </div>
      </div>
    </FichaConsulta>
  );
}

import { useCallback } from 'react';
import { GenericTable } from '../../components/crud/generic-table';
import { campanhaApi } from '../../services/12-campanha/api/campanha.api';
import {
  ORDEM_STATUS_CAMPANHA,
  ROTULO_STATUS_CAMPANHA,
} from '../../services/12-campanha/constants/status-campanha.constants';
import { areaConhecimentoApi } from '../../services/8-area-conhecimento/api/area-conhecimento.api';
import { usuarioApi } from '../../services/1-usuario/api/usuario.api';
import { logAuditoriaApi } from '../../services/27-log-auditoria/api/log-auditoria.api';
import type { PropsPagina } from '../../services/router/pagina.type';
import type { CampanhaResponse } from '../../services/12-campanha/type/campanha.type';

function formatarReais(valor: number | null): string {
  return Number(valor ?? 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
}

interface CampanhaLinha extends Omit<CampanhaResponse, 'status' | 'metaFinanceira' | 'valorBrutoArrecadado'> {
  status: string;
  pesquisador: string;
  area: string;
  metaFinanceira: string;
  valorBrutoArrecadado: string;
}

// Aba "Campanhas" do painel admin (23-08-2026, pedido do Lucas: "tipo o
// Menu de Usuários") - vive na rota /admin/campanhas. Sem rotaBase (sem
// Alterar/Excluir): campanha não tem endpoint de exclusão no backend
// (soft-delete via status, não linha removida), e editar campos foge do
// que um formulário genérico deveria fazer aqui - os campos editáveis
// dependem do status (congelados depois de aprovada) e a
// aprovação/rejeição têm regras próprias (ver PROXIMOS_MODULOS.md, Grupo
// 6, "Aprovar Campanhas" - tela dedicada ainda não construída). Por
// enquanto, só listar + consultar; hoje quem precisa criar/aprovar
// campanha de teste usa o Campo de Testes (views/campo-testes).
export function ListarCampanhas({ auth }: PropsPagina) {
  // Mesmo padrão de junção client-side de listar-usuarios.jsx (coluna
  // "papel"): busca campanhas + usuários + áreas numa vez só, junta no
  // navegador - os dois `.catch(() => [])` seguem o mesmo espírito:
  // se um catálogo falhar, a tabela continua de pé, só sem aquele nome
  // resolvido (mostra o id cru em vez de travar a tela inteira).
  const listarCampanhas = useCallback(async (): Promise<CampanhaLinha[]> => {
    const [campanhas, usuarios, areas] = await Promise.all([
      campanhaApi.listar(auth.authFetch),
      usuarioApi.listar(auth.authFetch).catch(() => []),
      areaConhecimentoApi.listar(auth.authFetch).catch(() => []),
    ]);

    const nomePorIdUsuario = new Map(usuarios.map((usuario) => [usuario.idUsuario, usuario.nome]));
    const nomePorIdArea = new Map(areas.map((area) => [area.idAreaConhecimento, area.nome]));

    return campanhas.map((campanha) => ({
      ...campanha,
      status: ROTULO_STATUS_CAMPANHA[campanha.status] ?? campanha.status,
      pesquisador: nomePorIdUsuario.get(campanha.idUsuario) ?? `#${campanha.idUsuario}`,
      area: nomePorIdArea.get(campanha.idAreaConhecimento) ?? `#${campanha.idAreaConhecimento}`,
      metaFinanceira: formatarReais(campanha.metaFinanceira),
      valorBrutoArrecadado: formatarReais(campanha.valorBrutoArrecadado),
    }));
  }, [auth.authFetch]);

  const buscarLogCampanha = useCallback(
    (pagina: number) => logAuditoriaApi.listarPorTabela(auth.authFetch, 'campanha', pagina),
    [auth.authFetch],
  );

  return (
    <div className="admin-content-painel">
      <GenericTable
        titulo="Campanhas"
        // largura igual nas 4 (25-08-2026, pedido do Lucas: mesma ideia de
        // Tipos de Link/Pesquisadores - "status"/"pesquisador"/"meta"/
        // "arrecadado" ficando cada um com um tamanho, "arrecadado" nem
        // tinha `centralizar` (inconsistência real com "meta", ao lado).
        // 10rem (não 8rem como em Pesquisadores) porque "status" aqui tem
        // valor bem mais longo que um badge normal (ex.: "Encerrado
        // (moderação)", 22 caracteres) - ainda pode quebrar em 2 linhas
        // nesse caso raro (nenhum white-space:nowrap forçado), só não
        // pede uma coluna gigante à toa pros valores curtos, que são a
        // maioria.
        // "título" também ganhou `largura` própria (18rem, ACHADO do
        // Lucas: sem largura nenhuma, virou a ÚNICA coluna "livre" da
        // tabela - absorvia sozinha TODO o espaço sobrando, já que as
        // outras 4 agora são fixas, mesmo problema que "nome"/"papel" já
        // tinham em Usuários antes de darmos largura fixa às vizinhas).
        // Diferente das 4 acima, sem `centralizar` - é a coluna principal
        // de texto (o "nome" desta tabela), fica alinhada à esquerda.
        // Texto quebra livremente dentro dos 18rem (nenhum nowrap
        // forçado, igual qualquer outra coluna de texto) - título de
        // campanha comprido agora ganha 2-3 linhas em vez de esticar a
        // coluna.
        colunas={[
          { chave: 'idCampanha', rotulo: 'id' },
          { chave: 'titulo', rotulo: 'título', largura: '28rem' },
          { chave: 'status', rotulo: 'status', centralizar: true, largura: '10rem' },
          { chave: 'pesquisador', rotulo: 'pesquisador', centralizar: true, largura: '10rem' },
          { chave: 'metaFinanceira', rotulo: 'meta', centralizar: true, largura: '10rem' },
          { chave: 'valorBrutoArrecadado', rotulo: 'arrecadado', centralizar: true, largura: '10rem' },
        ]}
        chavePrimaria="idCampanha"
        listar={listarCampanhas}
        rotaBase="/admin/campanhas"
        acoes={['consultar']}
        // "Área" (25-08-2026, pedido do Lucas: "tabela muito poluída") saiu
        // das colunas visíveis e virou filtro - o dado (`linha.area`)
        // continua vindo de listarCampanhas normalmente, filtro por faceta
        // não depende da coluna existir na tabela, só do campo existir na
        // linha.
        filtrosFacetados={[
          { chave: 'status', rotulo: 'Status', ordem: ORDEM_STATUS_CAMPANHA.map((s) => ROTULO_STATUS_CAMPANHA[s]) },
          { chave: 'area', rotulo: 'Área' },
        ]}
        buscarLog={buscarLogCampanha}
      />
    </div>
  );
}

import { useEffect, useState } from 'react';
import type { FormEvent } from 'react';
import { useNavigate, useParams } from 'react-router';
import { CampoSomenteLeitura } from '../../components/crud/campo-somente-leitura';
import { CartaoFormulario } from '../../components/crud/cartao-formulario';
import { useAvisoAlteracaoNaoSalva } from '../../components/crud/use-alteracao-nao-salva';
import { useErroToast } from '../../components/layout/use-erro-toast';
import { useToast } from '../../components/layout/use-toast';
import { papelApi } from '../../services/2-papel-permissao/api/papel-permissao.api';
import type { PropsPagina } from '../../services/router/pagina.type';

// Só existe (03-08-2026) porque `papel.codigo` (ver 01_extensoes_enums_
// tabelas.sql [01-B]) tornou seguro renomear um papel pelo painel - antes,
// 3 triggers de RBAC reconheciam 'admin'/'pesquisador'/'usuario' pelo TEXTO
// do nome, e renomear teria quebrado essas automações em silêncio. Agora
// as triggers leem `codigo` (nunca exposto/editável aqui), então `nome` (o
// rótulo) pode mudar livremente sem risco nenhum pro RBAC.
//
// Só "Alterar" existe pra papel (sem Consultar - a listagem já mostra
// id/nome, um 3º campo não ganharia nada; sem Excluir - apagar um papel
// usado em usuario_papel/papel_permissao é decisão maior, fora de escopo).
export function AlterarPapel({ auth }: PropsPagina) {
  const { id = '' } = useParams();
  const navigate = useNavigate();
  const { mostrar } = useToast();
  const { erro, reportarErro, limparErro } = useErroToast();
  const [nome, setNome] = useState('');
  const [nomeOriginal, setNomeOriginal] = useState('');
  const [carregando, setCarregando] = useState(true);
  const [enviando, setEnviando] = useState(false);
  const [encontrado, setEncontrado] = useState(false);

  useEffect(() => {
    // Não existe GET /papel/:id (só findall) - a lista inteira é pequena
    // (7 papéis), buscar tudo e filtrar pelo id é mais simples que criar
    // um endpoint novo só pra isso.
    papelApi
      .listar(auth.authFetch)
      .then((papeis) => {
        const papel = papeis.find((p) => String(p.idPapel) === id);
        if (papel) {
          setNome(papel.nome);
          setNomeOriginal(papel.nome);
          setEncontrado(true);
        }
      })
      .catch(reportarErro)
      .finally(() => setCarregando(false));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  const sujo = encontrado && nome !== nomeOriginal;
  useAvisoAlteracaoNaoSalva(sujo);

  const aoCancelar = () => {
    if (sujo && !window.confirm('Você tem alterações não salvas. Sair mesmo assim?')) {
      return;
    }
    navigate(-1);
  };

  const aoSalvar = async (evento: FormEvent<HTMLFormElement>) => {
    evento.preventDefault();
    limparErro();
    setEnviando(true);
    try {
      await papelApi.atualizar(auth.authFetch, id, { nome });
      mostrar('Papel alterado com sucesso.', `ID: ${id} foi alterado`);
      navigate(-1);
    } catch (erroRequisicao) {
      reportarErro(erroRequisicao);
    } finally {
      setEnviando(false);
    }
  };

  return (
    <CartaoFormulario
      icone="fa-user-tag"
      titulo="Alterar Papel"
      subtitulo="Só o nome exibido muda, o identificador interno usado pelas regras do sistema nunca é afetado."
      rodape={
        encontrado && (
          <div className="flex gap-3">
            <button type="button" onClick={aoCancelar} className="btn btn-secondary flex-1">
              Cancelar
            </button>
            <button
              type="submit"
              form="form-alterar-papel"
              disabled={enviando || !sujo}
              className="btn btn-primary flex-1"
            >
              {enviando ? 'Salvando...' : 'Salvar'}
            </button>
          </div>
        )
      }
    >
      {carregando ? (
        <p className="p-10 text-center text-sm texto-fraco">Carregando...</p>
      ) : !encontrado ? (
        <p className="p-10 text-center text-red-700 text-sm font-bold">
          {erro || `Papel ${id} não encontrado.`}
        </p>
      ) : (
        <form id="form-alterar-papel" onSubmit={aoSalvar} className="p-10 space-y-6">
          {erro && <p className="text-red-700 text-sm font-bold text-center">{erro}</p>}

          <CampoSomenteLeitura rotulo="id" valor={id} />

          <div>
            <label className="rotulo-campo">
              Nome
            </label>
            <input
              type="text"
              value={nome}
              onChange={(evento) => setNome(evento.target.value)}
              required
              maxLength={50}
              className="input-padrao"
            />
          </div>
        </form>
      )}
    </CartaoFormulario>
  );
}

import { useCallback, useEffect, useState } from 'react';
import { Tooltip } from '../../components/layout/tooltip';
import { useErroToast } from '../../components/layout/use-erro-toast';
import { useToast } from '../../components/layout/use-toast';
import {
  papelApi,
  papelPermissaoApi,
  permissaoApi,
} from '../../services/2-papel-permissao/api/papel-permissao.api';
import { nomeAmigavelPermissao } from '../../services/2-papel-permissao/constants/permissao-nomes-amigaveis';
import type { AuthFetch } from '../../services/3-auth/type/auth.type';
import type { PapelResponse, PermissaoResponse } from '../../services/2-papel-permissao/type/papel-permissao.type';

// Substituiu a antiga tabela "Papel × Permissão" (linhas repetindo
// "admin | admin | ..." - achado de uma IA: ~40 linhas pra mostrar o
// que uma matriz mostra em muito menos espaço). Não usa GenericTable - é
// um formato fundamentalmente diferente (matriz, não lista de linha+ações).
//
// Clicável desde 03-08-2026 (pedido do Lucas: "o administrador precisa ter
// poder absoluto pelo painel admin, nunca mais precisará acessar o banco
// depois") - cada célula agora concede/revoga a permissão daquele papel,
// via `papelPermissaoApi.atribuir/remover` (RLS exige a permissão
// 'papel_gerenciar', ver [04-B-1] em 04_rls_policies.sql).
//
// Linhas/colunas vêm do CATÁLOGO COMPLETO (`papelApi`/`permissaoApi`), não
// só das combinações já concedidas (`papelPermissaoApi.listar`) - senão um
// papel ou permissão sem nenhum vínculo hoje (ex.: 'usuario',
// 'pesquisador') nunca apareceria pra admin conceder a primeira permissão
// a ele pelo painel, o que contradiz o próprio objetivo de "nunca precisar
// mexer no banco". `papel`/`permissao` em si continuam só-leitura - criar
// um papel ou permissão novos (não só conceder uma combinação já
// existente) é decisão maior, fora de escopo aqui.
const TEXTO_TOOLTIP_MATRIZ =
  'Todo papel e toda permissão cadastrados aparecem aqui, mesmo sem ' +
  "nenhum vínculo ainda (ex.: 'usuario'/'pesquisador' começam sem nenhuma " +
  'permissão nomeada, o acesso deles normalmente é por serem donos do ' +
  'próprio dado, não por permissão, mas nada impede conceder uma se ' +
  'precisar). Clique numa célula pra conceder ou revogar.';

// Colunas em ordem de poder (maior pro menor), não alfabética - pedido do
// Lucas, 03-08-2026.
//
// CORRIGIDO (07-08-2026, achado do Lucas: "renomeei 'admin' pra 'admin
// teste' e a coluna pulou pro fim da matriz"): a ordenação comparava o
// NOME contra uma lista fixa de nomes esperados - assim que o admin usa o
// recurso de renomear papel (alterar-papel.jsx, também 07-08-2026), o nome
// novo não bate com nada da lista e a coluna cai pro fim. `id_papel` nunca
// muda (só `nome` é editável) e, desde a reordenação do seed
// (07_seed_dados.sql [07-B-1], mesma data), já nasce na ordem de poder
// certa num banco novo - ordenar por ele resolve os dois problemas de
// uma vez, sem precisar de lista nenhuma pra manter sincronizada.
function ordenarPapeisPorPoder(a: PapelResponse, b: PapelResponse): number {
  return a.idPapel - b.idPapel;
}

interface MatrizPapelPermissaoProps {
  authFetch: AuthFetch;
}

export function MatrizPapelPermissao({ authFetch }: MatrizPapelPermissaoProps) {
  const { mostrar } = useToast();
  const { erro, reportarErro, limparErro } = useErroToast();
  const [papeis, setPapeis] = useState<PapelResponse[]>([]);
  const [permissoes, setPermissoes] = useState<PermissaoResponse[]>([]);
  const [concedidos, setConcedidos] = useState<Set<string>>(new Set());
  const [carregando, setCarregando] = useState(true);
  const [celulaAlterando, setCelulaAlterando] = useState<string | null>(null);

  const recarregar = useCallback(() => {
    setCarregando(true);
    limparErro();
    Promise.all([
      papelApi.listar(authFetch),
      permissaoApi.listar(authFetch),
      papelPermissaoApi.listar(authFetch),
    ])
      .then(([listaPapeis, listaPermissoes, vinculos]) => {
        setPapeis([...listaPapeis].sort(ordenarPapeisPorPoder));
        // Ordena pelo nome AMIGÁVEL (09-08-2026), não pelo código cru - é
        // o que aparece na tela, então é o que precisa estar em ordem
        // alfabética visível pra quem lê.
        setPermissoes(
          [...listaPermissoes].sort((a, b) =>
            nomeAmigavelPermissao(a.nome).localeCompare(nomeAmigavelPermissao(b.nome)),
          ),
        );
        setConcedidos(new Set(vinculos.map((v) => `${v.idPapel}-${v.idPermissao}`)));
      })
      .catch(reportarErro)
      .finally(() => setCarregando(false));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [authFetch]);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    recarregar();
  }, [recarregar]);

  const alternar = async (
    idPapel: number,
    nomePapel: string,
    idPermissao: number,
    nomePermissao: string,
    concedidoAtual: boolean,
  ) => {
    const chave = `${idPapel}-${idPermissao}`;
    limparErro();
    setCelulaAlterando(chave);
    try {
      if (concedidoAtual) {
        await papelPermissaoApi.remover(authFetch, idPapel, idPermissao);
        mostrar(
          'Permissão revogada com sucesso.',
          `O papel "${nomePapel}" perdeu a permissão "${nomePermissao}"`,
        );
      } else {
        await papelPermissaoApi.atribuir(authFetch, idPapel, idPermissao);
        mostrar(
          'Permissão concedida com sucesso.',
          `O papel "${nomePapel}" agora tem a permissão "${nomePermissao}"`,
        );
      }
      recarregar();
    } catch (erroRequisicao) {
      reportarErro(erroRequisicao);
    } finally {
      setCelulaAlterando(null);
    }
  };

  return (
    <section className="crud-secao">
      <h2 className="titulo-secao flex items-center">
        Papel × Permissão
        <Tooltip texto={TEXTO_TOOLTIP_MATRIZ} />
      </h2>

      {carregando ? (
        <div className="animate-pulse h-32 fundo-sutil rounded"></div>
      ) : (
        <div className="overflow-x-auto">
          <table className="crud-tabela">
            <thead>
              <tr>
                <th>Permissão</th>
                {papeis.map((papel) => (
                  <th key={papel.idPapel} className="text-center">
                    {papel.nome}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {permissoes.map((permissao) => (
                <tr key={permissao.idPermissao}>
                  {/* title com o código cru (09-08-2026) - a matriz é
                      estreita demais pra uma coluna "chave" própria (igual
                      a listagem de Permissões abaixo); hover cobre o
                      mesmo caso de uso pra quem precisa do valor literal. */}
                  <td title={permissao.nome}>{nomeAmigavelPermissao(permissao.nome)}</td>
                  {papeis.map((papel) => {
                    const chave = `${papel.idPapel}-${permissao.idPermissao}`;
                    const temPermissao = concedidos.has(chave);
                    return (
                      <td key={papel.idPapel} className="text-center">
                        <button
                          type="button"
                          onClick={() =>
                            alternar(
                              papel.idPapel,
                              papel.nome,
                              permissao.idPermissao,
                              nomeAmigavelPermissao(permissao.nome),
                              temPermissao,
                            )
                          }
                          disabled={celulaAlterando === chave}
                          title={
                            temPermissao
                              ? `Clique pra revogar de "${papel.nome}"`
                              : `Clique pra conceder pra "${papel.nome}"`
                          }
                          className={
                            'w-7 h-7 rounded-md font-bold transition-colors disabled:opacity-50 disabled:cursor-wait ' +
                            (temPermissao
                              ? 'texto-sucesso hover:bg-emerald-100'
                              : 'texto-fraco opacity-50 hover-fundo-sutil hover:opacity-100')
                          }
                        >
                          {celulaAlterando === chave ? '…' : temPermissao ? '✓' : '-'}
                        </button>
                      </td>
                    );
                  })}
                </tr>
              ))}
              {permissoes.length === 0 && (
                <tr>
                  <td colSpan={papeis.length + 1}>Nenhuma permissão cadastrada.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      )}

      {erro && <p className="crud-erro">{erro}</p>}
    </section>
  );
}

import { useState } from 'react';
import type { FormEvent } from 'react';
import { Link, useNavigate } from 'react-router';
import { useErroToast } from '../../components/layout/use-erro-toast';
import { buscarAtivo } from '../../services/5-termo-uso/api/termo-uso.api';
import { ErroHttp } from '../../services/constant/api/http.util';
import type { PropsPagina } from '../../services/router/pagina.type';
import type { TermoUsoResponseAtivo } from '../../services/5-termo-uso/type/termo-uso.type';

const REGEX_EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

// Requisitos do medidor de força de senha (09-08-2026, Bloco D do prompt do
// uma IA) - só GUIA visual, o piso de verdade continua sendo o backend
// (CadastroRequestDto, @MinLength(8)): não faz sentido bloquear o clique
// aqui por maiúscula/número/símbolo se o servidor aceitaria com menos.
interface RequisitoSenha {
  chave: string;
  rotulo: string;
  testar: (s: string) => boolean;
}

const REQUISITOS_SENHA: RequisitoSenha[] = [
  { chave: 'tamanho', rotulo: 'Pelo menos 8 caracteres', testar: (s) => s.length >= 8 },
  { chave: 'maiuscula', rotulo: 'Uma letra maiúscula', testar: (s) => /[A-Z]/.test(s) },
  { chave: 'numero', rotulo: 'Um número', testar: (s) => /[0-9]/.test(s) },
  {
    chave: 'simbolo',
    rotulo: 'Um símbolo (!@#$...)',
    testar: (s) => /[^A-Za-z0-9]/.test(s),
  },
];

type CampoTocado = 'nome' | 'email' | 'senha' | 'confirmar';

// Tela de cadastro público (09-08-2026, Bloco D do prompt de uma IA) -
// primeira tela pública de verdade além de login. Só os 5 campos que
// importam pra criar a conta (nome/e-mail/senha/confirmar/aceite) - o
// resto (foto, perfil acadêmico...) mora em Minha Conta, editável depois,
// pra não derrubar a conversão do cadastro em si.
export function CadastroPage({ auth }: PropsPagina) {
  const navigate = useNavigate();
  const [nome, setNome] = useState('');
  const [email, setEmail] = useState('');
  const [senha, setSenha] = useState('');
  const [confirmarSenha, setConfirmarSenha] = useState('');
  const [mostrarSenha, setMostrarSenha] = useState(false);
  const [aceiteTermos, setAceiteTermos] = useState(false);
  const [enviando, setEnviando] = useState(false);
  const { erro, reportarErro, limparErro } = useErroToast();

  // "Tocado" (blur), não a cada tecla (09-08-2026, pedido explícito do
  // uma IA: validar enquanto a pessoa ainda está digitando o e-mail
  // acusa erro antes de ela terminar de escrever).
  const [tocado, setTocado] = useState<Record<CampoTocado, boolean>>({
    nome: false,
    email: false,
    senha: false,
    confirmar: false,
  });
  const marcarTocado = (campo: CampoTocado) => setTocado((atual) => ({ ...atual, [campo]: true }));

  const [erroEmailDuplicado, setErroEmailDuplicado] = useState(false);
  const [modalTermoAberto, setModalTermoAberto] = useState(false);
  const [termo, setTermo] = useState<TermoUsoResponseAtivo | null>(null);
  const [carregandoTermo, setCarregandoTermo] = useState(false);

  const abrirTermos = () => {
    setModalTermoAberto(true);
    if (!termo) {
      setCarregandoTermo(true);
      buscarAtivo()
        .then(setTermo)
        .catch(() => setTermo(null))
        .finally(() => setCarregandoTermo(false));
    }
  };

  const emailValido = REGEX_EMAIL.test(email);
  const senhasIguais = senha.length > 0 && senha === confirmarSenha;
  const requisitosCumpridos = REQUISITOS_SENHA.filter((r) => r.testar(senha)).length;
  const formularioValido =
    nome.trim().length >= 2 && emailValido && senha.length >= 8 && senhasIguais && aceiteTermos;

  const aoCadastrar = async (evento: FormEvent<HTMLFormElement>) => {
    evento.preventDefault();
    limparErro();
    setErroEmailDuplicado(false);
    setEnviando(true);
    try {
      const resultado = await auth.cadastrar(nome, email, senha, aceiteTermos);
      if (resultado.tokenVerificacaoEmailDev) {
        // Ambiente sem 4-mail ainda - link de verificação exibido direto,
        // com aviso claro de que é só dev (ver auth.service.cadastro.ts).
        window.alert(
          '[SÓ EM DEV] Link de verificação de e-mail (nenhum e-mail é enviado ainda):\n\n' +
            `${window.location.origin}/verificar-email?token=${resultado.tokenVerificacaoEmailDev}`,
        );
      }
      navigate('/');
    } catch (erroRequisicao) {
      if (erroRequisicao instanceof ErroHttp && erroRequisicao.status === 409) {
        setErroEmailDuplicado(true);
      }
      reportarErro(erroRequisicao);
    } finally {
      setEnviando(false);
    }
  };

  return (
    <div className="min-h-[calc(100vh-4rem)] flex items-center justify-center p-4 fundo-pagina">
      <div className="max-w-md w-full max-h-[calc(100vh-2rem)] fundo-cartao rounded-3xl shadow-2xl border borda-padrao overflow-hidden flex flex-col">
        <div className="p-10 text-center border-b borda-padrao fundo-sutil shrink-0">
          <div className="w-14 h-14 bg-primary rounded-2xl mx-auto flex items-center justify-center text-white font-bold text-2xl mb-5 shadow-lg">
            <i className="fa-solid fa-user-plus"></i>
          </div>
          <h2 className="text-3xl font-serif font-bold texto-forte mb-2">Criar conta</h2>
          <p className="text-sm texto-fraco font-medium">
            Leva menos de um minuto, o resto você completa depois, em Minha Conta.
          </p>
        </div>

        <form
          id="form-cadastro"
          onSubmit={aoCadastrar}
          className="p-10 space-y-5 overflow-y-auto min-h-0 flex-1"
        >
          {erro && <p className="text-red-700 text-sm font-bold text-center">{erro}</p>}

          <div>
            <label className="rotulo-campo">Nome</label>
            <input
              type="text"
              value={nome}
              onChange={(evento) => setNome(evento.target.value)}
              onBlur={() => marcarTocado('nome')}
              className="input-padrao"
              placeholder="Seu nome"
              autoComplete="name"
            />
            {tocado.nome && nome.trim().length < 2 && (
              <p className="text-xs texto-erro mt-1">Nome precisa ter pelo menos 2 caracteres.</p>
            )}
          </div>

          <div>
            <label className="rotulo-campo">E-mail</label>
            <input
              type="email"
              value={email}
              onChange={(evento) => {
                setEmail(evento.target.value);
                setErroEmailDuplicado(false);
              }}
              onBlur={() => marcarTocado('email')}
              className="input-padrao"
              placeholder="seu@email.com"
              autoComplete="email"
            />
            {tocado.email && email.length > 0 && !emailValido && (
              <p className="text-xs texto-erro mt-1">E-mail inválido.</p>
            )}
            {erroEmailDuplicado && (
              <p className="text-xs texto-erro mt-1">
                Já existe conta com este e-mail.{' '}
                <Link to="/login" className="font-bold underline">
                  Já tem conta? Entrar
                </Link>
              </p>
            )}
          </div>

          <div>
            <label className="rotulo-campo">Senha</label>
            <div className="relative">
              <input
                type={mostrarSenha ? 'text' : 'password'}
                value={senha}
                onChange={(evento) => setSenha(evento.target.value)}
                onBlur={() => marcarTocado('senha')}
                className="input-padrao pr-10"
                placeholder="••••••••"
                autoComplete="new-password"
              />
              <button
                type="button"
                onClick={() => setMostrarSenha((atual) => !atual)}
                aria-label={mostrarSenha ? 'Ocultar senha' : 'Mostrar senha'}
                className="absolute right-3 top-1/2 -translate-y-1/2 texto-fraco hover-texto-forte"
              >
                <i className={'fa-solid ' + (mostrarSenha ? 'fa-eye-slash' : 'fa-eye')}></i>
              </button>
            </div>

            {/* Medidor de força - barra + requisitos marcados conforme
                cumpridos, não uma mensagem de erro só depois do submit. */}
            {senha.length > 0 && (
              <div className="mt-2 space-y-1.5">
                <div className="flex gap-1">
                  {REQUISITOS_SENHA.map((r, indice) => (
                    <div
                      key={r.chave}
                      className={
                        'h-1 flex-1 rounded-full ' +
                        (indice < requisitosCumpridos ? 'bg-primary' : 'fundo-sutil')
                      }
                    ></div>
                  ))}
                </div>
                <ul className="grid grid-cols-2 gap-x-2 gap-y-1">
                  {REQUISITOS_SENHA.map((r) => {
                    const cumprido = r.testar(senha);
                    return (
                      <li
                        key={r.chave}
                        className={'text-xs flex items-center gap-1.5 ' + (cumprido ? 'texto-sucesso' : 'texto-fraco')}
                      >
                        <i className={'fa-solid ' + (cumprido ? 'fa-circle-check' : 'fa-circle') + ' text-[10px]'}></i>
                        {r.rotulo}
                      </li>
                    );
                  })}
                </ul>
              </div>
            )}
          </div>

          <div>
            <label className="rotulo-campo">Confirmar senha</label>
            <input
