        </form>

        <div className="p-6 border-t borda-padrao fundo-cartao shrink-0 space-y-3">
          <button
            type="submit"
            form="form-cadastro"
            disabled={!formularioValido || enviando}
            className="btn btn-primary w-full py-3.5 text-sm"
