            Direito de portabilidade (LGPD Art. 18), ainda não implementado neste protótipo.
          </p>
        </div>
        <button type="button" disabled className="btn btn-secondary opacity-50 cursor-not-allowed">
          Exportar
        </button>
      </div>

      <div className="rounded-lg border borda-forte fundo-erro p-4">
        <p className="text-sm font-bold texto-erro mb-2">Excluir minha conta</p>
        <p className="text-xs texto-erro mb-3">
          Marca sua conta como excluída (exclusão lógica), o login para de funcionar na hora.
          Não existe desfazer pelo painel.
        </p>
        {erro && <p className="text-xs texto-erro mb-2 font-bold">{erro}</p>}
        <label className="block text-xs font-bold texto-erro mb-1">
          Digite "{auth.usuario?.email}" pra confirmar
        </label>
        <input
          type="text"
          value={confirmacao}
          onChange={(evento) => setConfirmacao(evento.target.value)}
          className="input-padrao mb-3"
        />
        <button
          type="button"
          onClick={aoExcluir}
          disabled={!confirmado || excluindo}
          className="btn btn-danger"
        >
          {excluindo ? 'Excluindo...' : 'Excluir minha conta'}
        </button>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router';
import { CampoFicha, FichaConsulta, SecaoFicha } from '../../components/crud/ficha-consulta';
import { useErroToast } from '../../components/layout/use-erro-toast';
import { perfilPesquisadorApi } from '../../services/6-perfil-pesquisador/api/perfil-pesquisador.api';
import {
  ROTULO_STATUS_PESQUISADOR,
  ROTULO_TIPO_VINCULO,
  ROTULO_TITULO_ACADEMICO,
  classeBadgeStatusPesquisador,
} from '../../services/6-perfil-pesquisador/constants/status-pesquisador.constants';
import { usuarioApi } from '../../services/1-usuario/api/usuario.api';
import type { PropsPagina } from '../../services/router/pagina.type';
import type { PerfilPesquisadorResponse, PerfilPesquisadorResponseScore } from '../../services/6-perfil-pesquisador/type/perfil-pesquisador.type';

function formatarData(iso: string | null): string {
  return iso ? new Date(iso).toLocaleString('pt-BR') : 'Não definida';
}

function formatarCpf(cpf: string | null): string {
  if (!cpf) return 'Não visível (sem permissão sensível ou não é o dono)';
  return cpf.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/, '$1.$2.$3-$4');
}

// `nomeDimensao` vem cru do banco (snake_case, ex.: "atualizacao_campanha")
// - sem isso o rótulo colidia com o valor ao lado no grid de 2 colunas
// (CampoFicha), texto comprido demais pra largura da célula.
function formatarNomeDimensao(nome: string): string {
  return nome
    .split('_')
    .map((parte) => parte.charAt(0).toUpperCase() + parte.slice(1))
    .join(' ');
}

export function ConsultarPesquisador({ auth }: PropsPagina) {
  const { id = '' } = useParams();
  const navigate = useNavigate();
  const [perfil, setPerfil] = useState<PerfilPesquisadorResponse | null>(null);
  const [score, setScore] = useState<PerfilPesquisadorResponseScore | null>(null);
  const [nomeUsuario, setNomeUsuario] = useState<string | null>(null);
  const [carregando, setCarregando] = useState(true);
  const { erro, reportarErro } = useErroToast();

  useEffect(() => {
    Promise.all([
      perfilPesquisadorApi.buscar(auth.authFetch, id),
      perfilPesquisadorApi.buscarScore(auth.authFetch, id).catch(() => null),
      usuarioApi.buscar(auth.authFetch, id).then((u) => u.nome).catch(() => null),
    ])
      .then(([dadosPerfil, dadosScore, nome]) => {
        setPerfil(dadosPerfil);
        setScore(dadosScore);
        setNomeUsuario(nome);
      })
      .catch(reportarErro)
      .finally(() => setCarregando(false));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  if (carregando) {
    return <p className="p-10 text-center text-sm texto-fraco">Carregando...</p>;
  }

  if (!perfil) {
    return <p className="p-10 text-center text-red-700 text-sm font-bold">{erro}</p>;
  }

  return (
    <FichaConsulta
      titulo={nomeUsuario ?? `Usuário #${perfil.idUsuario}`}
      subtitulo={ROTULO_TITULO_ACADEMICO[perfil.tituloAcademico] ?? perfil.tituloAcademico}
      largura="larga"
      badges={[
        <span key="status" className={`badge ${classeBadgeStatusPesquisador(perfil.statusPesquisador)}`}>
          {ROTULO_STATUS_PESQUISADOR[perfil.statusPesquisador] ?? perfil.statusPesquisador}
        </span>,
        <span key="vinculo" className="badge badge-neutro">
          {ROTULO_TIPO_VINCULO[perfil.tipoVinculo] ?? perfil.tipoVinculo}
        </span>,
      ]}
      acoes={
        <button type="button" onClick={() => navigate(-1)} className="btn btn-secondary w-full">
          Voltar
        </button>
      }
    >
      <div className="grid lg:grid-cols-3 gap-6 items-start">
        <div className="lg:col-span-2 space-y-6">
          <SecaoFicha titulo="Dados">
            <CampoFicha rotulo="id" valor={perfil.idUsuario} />
            <CampoFicha rotulo="CPF" valor={formatarCpf(perfil.cpf)} />
            <CampoFicha rotulo="Vínculo institucional" valor={perfil.vinculoInstitucional ?? '-'} />
            <CampoFicha rotulo="Ativado em" valor={formatarData(perfil.ativadoEm)} />
          </SecaoFicha>
        </div>

        <div className="space-y-6">
          <SecaoFicha titulo="Score (Serasa do Pesquisador)">
            {score ? (
              <>
                <CampoFicha rotulo="Pontuação" largura="cheia" valor={`${score.scoreTotal} - ${score.rotulo}`} />
                {score.dimensoes.map((dimensao) => (
                  <CampoFicha
                    key={dimensao.nomeDimensao}
                    largura="cheia"
                    rotulo={formatarNomeDimensao(dimensao.nomeDimensao)}
                    valor={`${dimensao.pontosObtidos} pts (peso ${dimensao.peso})`}
                  />
                ))}
              </>
            ) : (
              <CampoFicha rotulo="Pontuação" largura="cheia" valor="Não disponível" />
            )}
          </SecaoFicha>
        </div>
      </div>
    </FichaConsulta>
  );
}

import { useCallback } from 'react';
import { GenericTable } from '../../components/crud/generic-table';
import { perfilPesquisadorApi } from '../../services/6-perfil-pesquisador/api/perfil-pesquisador.api';
import {
  ROTULO_STATUS_PESQUISADOR,
  ROTULO_TITULO_ACADEMICO,
} from '../../services/6-perfil-pesquisador/constants/status-pesquisador.constants';
import { usuarioApi } from '../../services/1-usuario/api/usuario.api';
import { logAuditoriaApi } from '../../services/27-log-auditoria/api/log-auditoria.api';
import type { PropsPagina } from '../../services/router/pagina.type';
import type { PerfilPesquisadorResponse } from '../../services/6-perfil-pesquisador/type/perfil-pesquisador.type';

interface PesquisadorLinha extends Omit<PerfilPesquisadorResponse, 'tituloAcademico' | 'statusPesquisador'> {
  nome: string;
  tituloAcademico: string;
  statusPesquisador: string;
}

// Aba "Pesquisadores" (23-08-2026, pedido do Lucas: "algum outro que eu
// esqueci?" - 6-perfil-pesquisador estava pronto e testado desde
// 22-08-2026, mas sem NENHUMA entrada de menu, igual Motivos de Denúncia
// estava antes). Mesmo raciocínio de sem-Alterar/sem-Excluir de
// listar-campanhas.jsx: editar campos de pesquisador tem regra própria
// (RF-017, correção de CPF é só via função SECURITY DEFINER, não um PATCH
// livre) e não existe endpoint de exclusão (status ativo/suspenso).
export function ListarPesquisadores({ auth }: PropsPagina) {
  const listarPesquisadores = useCallback(async (): Promise<PesquisadorLinha[]> => {
    const [pesquisadores, usuarios] = await Promise.all([
      perfilPesquisadorApi.listar(auth.authFetch),
      usuarioApi.listar(auth.authFetch).catch(() => []),
    ]);

    const nomePorIdUsuario = new Map(usuarios.map((usuario) => [usuario.idUsuario, usuario.nome]));

    return pesquisadores.map((pesquisador) => ({
      ...pesquisador,
      nome: nomePorIdUsuario.get(pesquisador.idUsuario) ?? `#${pesquisador.idUsuario}`,
      tituloAcademico: ROTULO_TITULO_ACADEMICO[pesquisador.tituloAcademico] ?? pesquisador.tituloAcademico,
      statusPesquisador: ROTULO_STATUS_PESQUISADOR[pesquisador.statusPesquisador] ?? pesquisador.statusPesquisador,
    }));
  }, [auth.authFetch]);

  const buscarLogPerfil = useCallback(
    (pagina: number) => logAuditoriaApi.listarPorTabela(auth.authFetch, 'perfil_pesquisador', pagina),
    [auth.authFetch],
  );

  return (
    <div className="admin-content-painel">
      <GenericTable
        titulo="Pesquisadores"
        colunas={[
          { chave: 'idUsuario', rotulo: 'id' },
          { chave: 'nome', rotulo: 'nome' },
          // largura igual nas 3 (25-08-2026, pedido do Lucas: "título,
          // status e score, cada um de um tamanho diferente e espalhados"
          // - mesma causa e mesmo remédio de Tipos de Link, "9.25rem"
          // pras 4 colunas Sim/Não: sem largura fixa, table-layout: auto
          // mede cada coluna pelo próprio maior valor ("Especialista" é
          // bem mais comprido que "Doutor"/"Ativo"), então cada uma
          // ficava com um tamanho diferente. `centralizar` em título
          // também (não teria entrado sozinho - é texto, não
          // número/booleano) pra alinhar com status/score, que já
          // centralizavam.
          { chave: 'tituloAcademico', rotulo: 'título', centralizar: true, largura: '8rem' },
          { chave: 'statusPesquisador', rotulo: 'status', centralizar: true, largura: '8rem' },
          { chave: 'scoreAtual', rotulo: 'score', largura: '8rem' },
        ]}
        chavePrimaria="idUsuario"
        listar={listarPesquisadores}
        rotaBase="/admin/pesquisadores"
        acoes={['consultar']}
        filtrosFacetados={[{ chave: 'statusPesquisador', rotulo: 'Status' }]}
        buscarLog={buscarLogPerfil}
      />
    </div>
  );
}

import { useEffect, useState } from 'react';
import type { FormEvent } from 'react';
import { useNavigate, useParams } from 'react-router';
import { CampoSomenteLeitura } from '../../components/crud/campo-somente-leitura';
import { CartaoFormulario } from '../../components/crud/cartao-formulario';
import { useAvisoAlteracaoNaoSalva } from '../../components/crud/use-alteracao-nao-salva';
import { SecaoFicha } from '../../components/crud/ficha-consulta';
import { useErroToast } from '../../components/layout/use-erro-toast';
import { useToast } from '../../components/layout/use-toast';
import { areaConhecimentoApi } from '../../services/8-area-conhecimento/api/area-conhecimento.api';
import type { PropsPagina } from '../../services/router/pagina.type';
import type { AreaConhecimentoResponse } from '../../services/8-area-conhecimento/type/area-conhecimento.type';

// `codigoCnpq`/"Grande área (pai)" não aparecem como campo editável (só
// leitura) porque AtualizarAreaConhecimentoRequestDto (Nest) não os
// aceita - são imutáveis depois de criada a linha: codigoCnpq é o
// identificador estável do catálogo CNPq (mesmo raciocínio de
// AlterarPapel sobre `papel.codigo`); idPai fica de fora por não existir
// checagem de ciclo/hierarquia no banco (ver comentário no DTO do
// backend). Só nome/ativo podem mudar.
export function AlterarAreaConhecimento({ auth }: PropsPagina) {
  const { id = '' } = useParams();
  const navigate = useNavigate();
  const { mostrar } = useToast();
  const { erro, reportarErro, limparErro } = useErroToast();
  const [area, setArea] = useState<AreaConhecimentoResponse | null>(null);
  const [nome, setNome] = useState('');
  const [ativo, setAtivo] = useState(true);
  const [carregando, setCarregando] = useState(true);
  const [enviando, setEnviando] = useState(false);

  useEffect(() => {
    areaConhecimentoApi
      .buscar(auth.authFetch, id)
      .then((dados) => {
        setArea(dados);
        setNome(dados.nome);
        setAtivo(dados.ativo);
      })
      .catch(reportarErro)
      .finally(() => setCarregando(false));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  const sujo = area !== null && (nome !== area.nome || ativo !== area.ativo);
  useAvisoAlteracaoNaoSalva(sujo);

  const aoCancelar = () => {
    if (sujo && !window.confirm('Você tem alterações não salvas. Sair mesmo assim?')) {
      return;
    }
    navigate(-1);
  };

  const aoSalvar = async (evento: FormEvent<HTMLFormElement>) => {
    evento.preventDefault();
    limparErro();
    setEnviando(true);
    try {
      await areaConhecimentoApi.atualizar(auth.authFetch, id, { nome, ativo });
      mostrar('Área de conhecimento alterada com sucesso.', `ID: ${id} foi alterada`);
      navigate(-1);
    } catch (erroRequisicao) {
      reportarErro(erroRequisicao);
    } finally {
      setEnviando(false);
    }
  };

  return (
    <CartaoFormulario
      icone="fa-diagram-project"
      titulo="Alterar Área de Conhecimento"
      rodape={
        area && (
          <div className="flex gap-3">
            <button type="button" onClick={aoCancelar} className="btn btn-secondary flex-1">
              Cancelar
            </button>
            <button
              type="submit"
              form="form-alterar-area-conhecimento"
              disabled={enviando || !sujo}
              className="btn btn-primary flex-1"
            >
              {enviando ? 'Salvando...' : 'Salvar'}
            </button>
          </div>
        )
      }
    >
      {carregando ? (
        <p className="p-10 text-center text-sm texto-fraco">Carregando...</p>
      ) : !area ? (
        <p className="p-10 text-center text-red-700 text-sm font-bold">{erro}</p>
      ) : (
        <form id="form-alterar-area-conhecimento" onSubmit={aoSalvar} className="p-10 space-y-6">
          {erro && <p className="text-red-700 text-sm font-bold text-center">{erro}</p>}

          <div className="flex items-center gap-3 pb-4 border-b borda-padrao">
            <div className="w-11 h-11 rounded-full bg-primary text-white flex items-center justify-center shrink-0">
              <i className="fa-solid fa-diagram-project"></i>
            </div>
            <div className="min-w-0">
              <p className="font-bold texto-forte truncate font-mono text-sm">
                {area.codigoCnpq}
              </p>
              <p className="text-xs texto-fraco">
                Área de conhecimento #{area.idAreaConhecimento}
              </p>
            </div>
          </div>

          <SecaoFicha titulo="Dados">
            <CampoSomenteLeitura rotulo="Código CNPq" valor={area.codigoCnpq} />
            <CampoSomenteLeitura
              rotulo="Grande área (pai)"
              valor={area.nomePai ?? 'Nenhuma (é uma grande área raiz)'}
            />
          </SecaoFicha>

          <SecaoFicha titulo="Editar">
            <div className="sm:col-span-2">
              <label className="rotulo-campo">Nome</label>
              <input
                type="text"
                value={nome}
                onChange={(evento) => setNome(evento.target.value)}
                required
                maxLength={100}
                className="input-padrao"
              />
            </div>

            <label className="sm:col-span-2 flex items-center gap-2 text-sm font-semibold texto-padrao">
              <input
                type="checkbox"
                checked={ativo}
                onChange={(evento) => setAtivo(evento.target.checked)}
              />
              Ativo
            </label>
          </SecaoFicha>
        </form>
      )}
    </CartaoFormulario>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router';
import { CampoFicha, FichaConsulta, SecaoFicha } from '../../components/crud/ficha-consulta';
import { useErroToast } from '../../components/layout/use-erro-toast';
import { areaConhecimentoApi } from '../../services/8-area-conhecimento/api/area-conhecimento.api';
import type { PropsPagina } from '../../services/router/pagina.type';
import type { AreaConhecimentoResponse } from '../../services/8-area-conhecimento/type/area-conhecimento.type';

export function ConsultarAreaConhecimento({ auth }: PropsPagina) {
  const { id = '' } = useParams();
  const navigate = useNavigate();
  const [area, setArea] = useState<AreaConhecimentoResponse | null>(null);
  const [carregando, setCarregando] = useState(true);
  const { erro, reportarErro } = useErroToast();

  useEffect(() => {
    areaConhecimentoApi
      .buscar(auth.authFetch, id)
      .then(setArea)
      .catch(reportarErro)
      .finally(() => setCarregando(false));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  if (carregando) {
    return <p className="p-10 text-center text-sm texto-fraco">Carregando...</p>;
