    >
      <SecaoFicha titulo="Dados">
        <CampoFicha rotulo="id" valor={area.idAreaConhecimento} />
        <CampoFicha rotulo="Código CNPq" valor={area.codigoCnpq} />
        <CampoFicha rotulo="Nome" valor={area.nome} largura="cheia" />
        <CampoFicha rotulo="Grande área (pai)" valor={area.nomePai} largura="cheia" />
      </SecaoFicha>
    </FichaConsulta>
  );
}

import { useEffect, useState } from 'react';
import type { FormEvent } from 'react';
import { useNavigate } from 'react-router';
import { CartaoFormulario } from '../../components/crud/cartao-formulario';
import { useErroToast } from '../../components/layout/use-erro-toast';
import { useToast } from '../../components/layout/use-toast';
import { areaConhecimentoApi } from '../../services/8-area-conhecimento/api/area-conhecimento.api';
import type { PropsPagina } from '../../services/router/pagina.type';
import type { AreaConhecimentoResponse } from '../../services/8-area-conhecimento/type/area-conhecimento.type';

// Formato oficial do código CNPq (grande área.área.subárea.especialidade,
// sempre 2 dígitos por nível, ex.: '1.03.00.00') - mesma validação de
// CriarAreaConhecimentoRequestDto (Nest), duplicada aqui só pra dar
// feedback ANTES de bater no backend, não pra substituir a validação de
// lá (mesma convenção de REGEX_CHAVE_VALIDA em criar-configuracao.jsx).
const REGEX_CODIGO_CNPQ = /^\d{1,2}\.\d{2}\.\d{2}\.\d{2}$/;

export function CriarAreaConhecimento({ auth }: PropsPagina) {
  const navigate = useNavigate();
  const { mostrar } = useToast();
  const { erro, reportarErro, limparErro } = useErroToast();
  const [codigoCnpq, setCodigoCnpq] = useState('');
  const [nome, setNome] = useState('');
  const [idPai, setIdPai] = useState('');
  const [grandesAreas, setGrandesAreas] = useState<AreaConhecimentoResponse[]>([]);
  const [carregandoGrandesAreas, setCarregandoGrandesAreas] = useState(true);
  const [enviando, setEnviando] = useState(false);

  // Combo "Grande área" só lista raízes de verdade (`raiz: true`, vira
  // `?raiz=true` - ver ListarAreaConhecimentoQueryDto no backend). A
  // mesma regra que area-conhecimento.service.create.ts confere no INSERT
  // (idPai precisa ser uma grande área raiz, nunca outra área de nível 2)
  // já fica garantida por construção aqui: não dá pra escolher algo que
  // não seja raiz.
  useEffect(() => {
    areaConhecimentoApi
      .listar(auth.authFetch, { raiz: true, ativo: true })
      .then(setGrandesAreas)
      .catch(reportarErro)
      .finally(() => setCarregandoGrandesAreas(false));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Só valida depois que a pessoa digitou alguma coisa - mesmo raciocínio
  // de chaveInvalida em criar-configuracao.jsx.
  const codigoInvalido = codigoCnpq.length > 0 && !REGEX_CODIGO_CNPQ.test(codigoCnpq);

  const aoCriar = async (evento: FormEvent<HTMLFormElement>) => {
    evento.preventDefault();
    limparErro();
    setEnviando(true);
    try {
      const areaCriada = await areaConhecimentoApi.criar(auth.authFetch, {
        codigoCnpq,
        nome,
        ...(idPai ? { idPai: Number(idPai) } : {}),
      });
      mostrar(
        'Área de conhecimento cadastrada com sucesso.',
        `A nova área possui o ID: ${areaCriada.idAreaConhecimento}`,
      );
      navigate(-1);
    } catch (erroRequisicao) {
      reportarErro(erroRequisicao);
    } finally {
      setEnviando(false);
    }
  };

  return (
    <CartaoFormulario
      icone="fa-diagram-project"
      titulo="Criar Área de Conhecimento"
      subtitulo="Preencha os dados abaixo para cadastrar uma nova área do conhecimento."
    >
      <form onSubmit={aoCriar} className="p-10 space-y-6">
        {erro && <p className="text-red-700 text-sm font-bold text-center">{erro}</p>}

        <div>
          <label className="rotulo-campo">Código CNPq</label>
          <input
            type="text"
            value={codigoCnpq}
            onChange={(evento) => setCodigoCnpq(evento.target.value)}
            required
            placeholder="ex.: 1.03.00.00"
            aria-invalid={codigoInvalido}
            className={'input-padrao font-mono' + (codigoInvalido ? ' border-red-500' : '')}
          />
          {codigoInvalido ? (
            <p className="text-xs text-red-600 font-semibold mt-1">
              Precisa seguir o formato do CNPq: 4 níveis de 2 dígitos separados por ponto (ex.:
              "1.03.00.00").
            </p>
          ) : (
            <p className="text-xs texto-fraco mt-1">
              Formato de classificação utilizado pelo CNPq - grande área.área.subárea.especialidade.
            </p>
          )}
        </div>

        <div>
          <label className="rotulo-campo">Nome</label>
          <input
            type="text"
            value={nome}
            onChange={(evento) => setNome(evento.target.value)}
            required
            maxLength={100}
            className="input-padrao"
          />
        </div>

        <div>
          <label className="rotulo-campo">Grande área (pai)</label>
          <select
            value={idPai}
            onChange={(evento) => setIdPai(evento.target.value)}
            disabled={carregandoGrandesAreas}
            className="input-padrao"
          >
            <option value="">- Nenhuma (esta é uma grande área raiz) -</option>
            {grandesAreas.map((area) => (
              <option key={area.idAreaConhecimento} value={area.idAreaConhecimento}>
                {area.nome}
              </option>
            ))}
          </select>
          <p className="text-xs texto-fraco mt-1">
            Deixe em branco pra cadastrar uma grande área nova; escolha uma existente pra
            cadastrar uma área filha dela (a hierarquia tem só 2 níveis).
          </p>
        </div>

        <div className="flex gap-3 pt-2">
          <button type="button" onClick={() => navigate(-1)} className="btn btn-secondary flex-1">
            Cancelar
          </button>
          <button
            type="submit"
            disabled={enviando || codigoInvalido}
            className="btn btn-primary flex-1"
          >
            {enviando ? 'Criando...' : 'Criar'}
          </button>
        </div>
      </form>
    </CartaoFormulario>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router';
import { CartaoFormulario } from '../../components/crud/cartao-formulario';
import { CampoFicha, SecaoFicha } from '../../components/crud/ficha-consulta';
import { useErroToast } from '../../components/layout/use-erro-toast';
import { useToast } from '../../components/layout/use-toast';
import { areaConhecimentoApi } from '../../services/8-area-conhecimento/api/area-conhecimento.api';
import type { PropsPagina } from '../../services/router/pagina.type';
import type { AreaConhecimentoResponse } from '../../services/8-area-conhecimento/type/area-conhecimento.type';

// Mesmo padrão de ExcluirConfiguracao (11-configuracoes) - ver comentário
// completo lá. Diferente de configuracao, area_conhecimento é referenciada
// por campanha e por outras áreas filhas (id_pai) sem CASCADE - se estiver
// em uso, o backend responde 409 com uma mensagem própria (ver
// area-conhecimento.service.remove.ts), exibida aqui pelo useErroToast
// normal, sem tratamento especial.
export function ExcluirAreaConhecimento({ auth }: PropsPagina) {
  const { id = '' } = useParams();
  const navigate = useNavigate();
  const { mostrar } = useToast();
  const { erro, reportarErro, limparErro } = useErroToast();
  const [area, setArea] = useState<AreaConhecimentoResponse | null>(null);
  const [carregando, setCarregando] = useState(true);
  const [excluindo, setExcluindo] = useState(false);

  useEffect(() => {
    areaConhecimentoApi
      .buscar(auth.authFetch, id)
      .then(setArea)
      .catch(reportarErro)
      .finally(() => setCarregando(false));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  const aoConfirmar = async () => {
    limparErro();
    setExcluindo(true);
    try {
      await areaConhecimentoApi.remover(auth.authFetch, id);
      mostrar('Área de conhecimento excluída com sucesso.', `ID: ${id} foi excluído`);
      navigate(-1);
    } catch (erroRequisicao) {
      reportarErro(erroRequisicao);
      setExcluindo(false);
    }
  };

  return (
    <CartaoFormulario
      icone="fa-triangle-exclamation"
      titulo="Excluir Área de Conhecimento"
      subtitulo="Esta ação não pode ser desfeita."
      variante="perigo"
      rodape={
        area && (
          <div className="flex gap-3">
            <button type="button" onClick={() => navigate(-1)} className="btn btn-secondary flex-1">
              Cancelar
            </button>
            <button
              type="button"
              onClick={aoConfirmar}
              disabled={excluindo}
              className="btn btn-danger flex-1"
            >
              {excluindo ? 'Excluindo...' : 'Confirmar exclusão'}
            </button>
          </div>
        )
      }
    >
      {carregando ? (
        <p className="p-10 text-center text-sm texto-fraco">Carregando...</p>
      ) : !area ? (
        <p className="p-10 text-center text-red-700 text-sm font-bold">{erro}</p>
      ) : (
        <div className="p-10 space-y-6">
          {erro && <p className="text-red-700 text-sm font-bold text-center">{erro}</p>}

          <SecaoFicha titulo="O que será excluído">
            <CampoFicha rotulo="Código CNPq" valor={area.codigoCnpq} />
            <CampoFicha rotulo="Nome" valor={area.nome} largura="cheia" />
            <CampoFicha rotulo="Grande área (pai)" valor={area.nomePai} largura="cheia" />
          </SecaoFicha>

          <div className="rounded-lg border borda-forte fundo-erro p-4 text-sm texto-erro">
            <p className="font-bold mb-1">
              <i className="fa-solid fa-circle-info mr-1"></i> O que acontece de verdade
            </p>
            <p>
              Se esta área ainda estiver vinculada a alguma campanha (ou a outra área filha), a
              exclusão é bloqueada pelo próprio banco - desative-a em vez de excluir. Se não
              estiver em uso, some do catálogo pra sempre, sem exclusão lógica.
            </p>
          </div>
        </div>
      )}
    </CartaoFormulario>
  );
}

import { useEffect, useState } from 'react';
import type { FormEvent } from 'react';
import { useNavigate, useParams } from 'react-router';
import { CampoSomenteLeitura } from '../../components/crud/campo-somente-leitura';
import { CartaoFormulario } from '../../components/crud/cartao-formulario';
import { useAvisoAlteracaoNaoSalva } from '../../components/crud/use-alteracao-nao-salva';
import { SecaoFicha } from '../../components/crud/ficha-consulta';
import { useErroToast } from '../../components/layout/use-erro-toast';
import { useToast } from '../../components/layout/use-toast';
import { tipoLinkApi } from '../../services/9-tipo-link/api/tipo-link.api';
import type { PropsPagina } from '../../services/router/pagina.type';
import type { TipoLinkResponse } from '../../services/9-tipo-link/type/tipo-link.type';

function regexValida(padrao: string): boolean {
  if (!padrao) {
    return true;
  }
  try {
    new RegExp(padrao);
    return true;
  } catch {
    return false;
  }
}

// "github.com, gist.github.com" -> ['github.com', 'gist.github.com'];
// "" (ou só espaços/vírgulas) -> [] - dominio é NOT NULL DEFAULT '{}'
// (mecanismo de validação PRINCIPAL, desde a revisão de 16-08-2026),
// array vazio é o único jeito de dizer "sem restrição de domínio", não
// mais `null`. Mesma função de criar-tipo-link.jsx, duplicada aqui - cada
// view deste módulo fica autocontida, mesmo padrão do resto do projeto.
function paraDominios(texto: string): string[] {
  return texto
    .split(',')
    .map((valor) => valor.trim())
    .filter(Boolean);
}

// `codigo` não aparece como campo editável (só leitura) porque
// AtualizarTipoLinkRequestDto (Nest) não o aceita - é a chave estável que
// calcular_score_perfil_academico() lê pra reconhecer Lattes/ORCID (mesmo
// raciocínio de AlterarPapel sobre `papel.codigo`/AlterarAreaConhecimento
// sobre `codigoCnpq`). Todo o resto pode mudar.
export function AlterarTipoLink({ auth }: PropsPagina) {
  const { id = '' } = useParams();
  const navigate = useNavigate();
  const { mostrar } = useToast();
  const { erro, reportarErro, limparErro } = useErroToast();
  const [tipo, setTipo] = useState<TipoLinkResponse | null>(null);
  const [nome, setNome] = useState('');
  const [ativo, setAtivo] = useState(true);
  const [regex, setRegex] = useState('');
  // Texto separado por vírgula na tela (ver paraDominios acima) -
  // `dominio` é o mecanismo de validação PRINCIPAL (array nativo do
  // Postgres, NOT NULL DEFAULT '{}'), mas não existe componente de "tags"
  // reutilizável no projeto ainda.
  const [dominioTexto, setDominioTexto] = useState('');
  const [permitePerfil, setPermitePerfil] = useState(true);
  const [permiteAtualizacao, setPermiteAtualizacao] = useState(false);
  const [permiteRecompensa, setPermiteRecompensa] = useState(false);
  const [carregando, setCarregando] = useState(true);
  const [enviando, setEnviando] = useState(false);

  useEffect(() => {
    tipoLinkApi
      .buscar(auth.authFetch, id)
      .then((dados) => {
        setTipo(dados);
        setNome(dados.nome);
        setAtivo(dados.ativo);
        setRegex(dados.regex ?? '');
        setDominioTexto(dados.dominio.join(', '));
        setPermitePerfil(dados.permitePerfil);
        setPermiteAtualizacao(dados.permiteAtualizacao);
        setPermiteRecompensa(dados.permiteRecompensa);
      })
      .catch(reportarErro)
      .finally(() => setCarregando(false));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  const sujo =
    tipo !== null &&
    (nome !== tipo.nome ||
      ativo !== tipo.ativo ||
      regex !== (tipo.regex ?? '') ||
      dominioTexto !== tipo.dominio.join(', ') ||
      permitePerfil !== tipo.permitePerfil ||
      permiteAtualizacao !== tipo.permiteAtualizacao ||
      permiteRecompensa !== tipo.permiteRecompensa);
  useAvisoAlteracaoNaoSalva(sujo);

  const regexInvalida = regex.length > 0 && !regexValida(regex);
  // CK_TIPO_LINK_ALGUM_ESCOPO (01_extensoes_enums_tabelas.sql) - mesma
  // checagem de CriarTipoLink, travando o botão Salvar ANTES de bater no
  // backend.
  const nenhumEscopoMarcado = !permitePerfil && !permiteAtualizacao && !permiteRecompensa;

  const aoCancelar = () => {
    if (sujo && !window.confirm('Você tem alterações não salvas. Sair mesmo assim?')) {
      return;
    }
    navigate(-1);
  };

  const aoSalvar = async (evento: FormEvent<HTMLFormElement>) => {
    evento.preventDefault();
    limparErro();
    setEnviando(true);
    try {
      await tipoLinkApi.atualizar(auth.authFetch, id, {
        nome,
        ativo,
        // '' vira `null` (limpa o campo) - regex é NULLABLE e
        // AtualizarTipoLinkRequestDto (Nest) aceita `null` explícito no
        // corpo pra isto. dominio NUNCA é `null` (NOT NULL DEFAULT '{}'
        // no banco) - array vazio já é o "limpo" por natureza, sem
        // precisar de fallback nenhum.
        regex: regex || null,
        dominio: paraDominios(dominioTexto),
        permitePerfil,
        permiteAtualizacao,
        permiteRecompensa,
      });
      mostrar('Tipo de link alterado com sucesso.', `ID: ${id} foi alterado`);
      navigate(-1);
    } catch (erroRequisicao) {
      reportarErro(erroRequisicao);
    } finally {
      setEnviando(false);
    }
  };

  return (
    <CartaoFormulario
      icone="fa-link"
      titulo="Alterar Tipo de Link"
      rodape={
        tipo && (
          <div className="flex gap-3">
            <button type="button" onClick={aoCancelar} className="btn btn-secondary flex-1">
              Cancelar
            </button>
            <button
              type="submit"
              form="form-alterar-tipo-link"
              disabled={enviando || !sujo || regexInvalida || nenhumEscopoMarcado}
              className="btn btn-primary flex-1"
            >
              {enviando ? 'Salvando...' : 'Salvar'}
            </button>
          </div>
        )
      }
    >
      {carregando ? (
        <p className="p-10 text-center text-sm texto-fraco">Carregando...</p>
      ) : !tipo ? (
        <p className="p-10 text-center text-red-700 text-sm font-bold">{erro}</p>
      ) : (
        <form id="form-alterar-tipo-link" onSubmit={aoSalvar} className="p-10 space-y-6">
          {erro && <p className="text-red-700 text-sm font-bold text-center">{erro}</p>}

          <div className="flex items-center gap-3 pb-4 border-b borda-padrao">
            <div className="w-11 h-11 rounded-full bg-primary text-white flex items-center justify-center shrink-0">
              <i className="fa-solid fa-link"></i>
            </div>
            <div className="min-w-0">
              <p className="font-bold texto-forte truncate font-mono text-sm">{tipo.codigo}</p>
              <p className="text-xs texto-fraco">Tipo de link #{tipo.idTipolink}</p>
            </div>
          </div>

          <SecaoFicha titulo="Dados">
            <CampoSomenteLeitura rotulo="Código" valor={tipo.codigo} />
          </SecaoFicha>

          <SecaoFicha titulo="Editar">
            <div className="sm:col-span-2">
              <label className="rotulo-campo">Nome</label>
              <input
                type="text"
                value={nome}
                onChange={(evento) => setNome(evento.target.value)}
                required
                maxLength={100}
                className="input-padrao"
              />
            </div>

            <div className="sm:col-span-2">
              <label className="rotulo-campo">Domínios permitidos</label>
              <input
                type="text"
                value={dominioTexto}
                onChange={(evento) => setDominioTexto(evento.target.value)}
                placeholder="ex.: github.com, gist.github.com"
                className="input-padrao"
              />
              <p className="text-xs texto-fraco mt-1">
                Mecanismo de validação principal: o host da URL precisa estar nesta lista. Um ou
                mais domínios separados por vírgula. Deixe em branco pra aceitar qualquer
                domínio.
              </p>
            </div>

            <div className="sm:col-span-2">
              <label className="rotulo-campo">Regex de validação (opcional)</label>
              <input
                type="text"
                value={regex}
                onChange={(evento) => setRegex(evento.target.value)}
                aria-invalid={regexInvalida}
                className={'input-padrao font-mono' + (regexInvalida ? ' border-red-500' : '')}
              />
              {regexInvalida ? (
                <p className="text-xs text-red-600 font-semibold mt-1">
                  Isto não é uma expressão regular válida.
                </p>
              ) : (
                <p className="text-xs texto-fraco mt-1">
                  Complemento opcional aos domínios acima. Deixe em branco quando o domínio já for
                  suficiente.
                </p>
              )}
            </div>


            <label className="sm:col-span-2 flex items-center gap-2 text-sm font-semibold texto-padrao">
              <input
                type="checkbox"
                checked={ativo}
                onChange={(evento) => setAtivo(evento.target.checked)}
              />
              Ativo
            </label>

            <div className="sm:col-span-2">
              <span className="rotulo-campo">Onde este tipo pode ser usado</span>
              <div className="space-y-2 mt-1">
                <label className="flex items-center gap-2 text-sm font-semibold texto-padrao">
                  <input
                    type="checkbox"
                    checked={permitePerfil}
                    onChange={(evento) => setPermitePerfil(evento.target.checked)}
                  />
                  Perfil do pesquisador
                </label>
                <label className="flex items-center gap-2 text-sm font-semibold texto-padrao">
                  <input
                    type="checkbox"
                    checked={permiteAtualizacao}
                    onChange={(evento) => setPermiteAtualizacao(evento.target.checked)}
                  />
                  Atualização de campanha
                </label>
                <label className="flex items-center gap-2 text-sm font-semibold texto-padrao">
                  <input
                    type="checkbox"
                    checked={permiteRecompensa}
                    onChange={(evento) => setPermiteRecompensa(evento.target.checked)}
                  />
                  Recompensa
                </label>
              </div>
              {nenhumEscopoMarcado && (
                <p className="text-xs text-red-600 font-semibold mt-1">
                  Pelo menos uma opção precisa ficar marcada.
                </p>
              )}
            </div>
          </SecaoFicha>
        </form>
      )}
    </CartaoFormulario>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router';
import { CampoFicha, FichaConsulta, SecaoFicha } from '../../components/crud/ficha-consulta';
import { useErroToast } from '../../components/layout/use-erro-toast';
import { tipoLinkApi } from '../../services/9-tipo-link/api/tipo-link.api';
import type { PropsPagina } from '../../services/router/pagina.type';
import type { TipoLinkResponse } from '../../services/9-tipo-link/type/tipo-link.type';

export function ConsultarTipoLink({ auth }: PropsPagina) {
  const { id = '' } = useParams();
  const navigate = useNavigate();
  const [tipo, setTipo] = useState<TipoLinkResponse | null>(null);
  const [carregando, setCarregando] = useState(true);
  const { erro, reportarErro } = useErroToast();

  useEffect(() => {
    tipoLinkApi
      .buscar(auth.authFetch, id)
      .then(setTipo)
      .catch(reportarErro)
      .finally(() => setCarregando(false));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  if (carregando) {
    return <p className="p-10 text-center text-sm texto-fraco">Carregando...</p>;
  }

  if (!tipo) {
    return <p className="p-10 text-center text-red-700 text-sm font-bold">{erro}</p>;
  }

  // Rótulos dos 3 escopos marcados (CK_TIPO_LINK_ALGUM_ESCOPO garante
  // pelo menos 1) - vira badge por escopo, não um badge Sim/Não por
  // campo: mais rápido de ler "onde isto pode ser usado" de relance.
  const escopos = [
    tipo.permitePerfil && 'Perfil',
    tipo.permiteAtualizacao && 'Atualização',
    tipo.permiteRecompensa && 'Recompensa',
  ].filter((escopo): escopo is string => Boolean(escopo));

  return (
    <FichaConsulta
      titulo={tipo.nome}
      subtitulo={tipo.codigo}
      badges={[
        <span key="ativo" className={'badge ' + (tipo.ativo ? 'badge-sucesso' : 'badge-neutro')}>
          {tipo.ativo ? 'Ativo' : 'Inativo'}
        </span>,
        ...escopos.map((escopo) => (
          <span key={escopo} className="badge badge-neutro">
            {escopo}
          </span>
        )),
      ]}
      acoes={
        <button type="button" onClick={() => navigate(-1)} className="btn btn-secondary w-full">
          Voltar
        </button>
      }
    >
      <SecaoFicha titulo="Dados">
        <CampoFicha rotulo="id" valor={tipo.idTipolink} />
        <CampoFicha rotulo="Código" valor={tipo.codigo} />
        <CampoFicha rotulo="Nome" valor={tipo.nome} largura="cheia" />
        <CampoFicha
          rotulo="Domínios permitidos"
          valor={tipo.dominio.length ? tipo.dominio.join(', ') : null}
          largura="cheia"
        />
        <CampoFicha rotulo="Regex de validação" valor={tipo.regex} largura="cheia" />
      </SecaoFicha>
    </FichaConsulta>
  );
}

import { useState } from 'react';
import type { FormEvent } from 'react';
import { useNavigate } from 'react-router';
import { CartaoFormulario } from '../../components/crud/cartao-formulario';
import { useErroToast } from '../../components/layout/use-erro-toast';
import { useToast } from '../../components/layout/use-toast';
import { tipoLinkApi } from '../../services/9-tipo-link/api/tipo-link.api';
import type { PropsPagina } from '../../services/router/pagina.type';

// Convenção de código (mesma ideia de REGEX_CHAVE_VALIDA em
// criar-configuracao.jsx) - MAIÚSCULO_COM_UNDERSCORE, igual todo `codigo`
// já seedado (LATTES, ORCID, RESEARCHGATE, LINKEDIN, GITHUB,
// SITE_INSTITUCIONAL, OUTRO - ver 07_seed_dados.sql [07-C-1]). Mesma
// validação de CriarTipoLinkRequestDto (Nest), duplicada aqui só pra dar
// feedback ANTES de bater no backend.
const REGEX_CODIGO_VALIDO = /^[A-Z0-9_]+$/;

function regexValida(padrao: string): boolean {
  if (!padrao) {
    return true;
  }
  try {
    new RegExp(padrao);
    return true;
  } catch {
    return false;
  }
}

// "github.com, gist.github.com" -> ['github.com', 'gist.github.com'];
// "" (ou só espaços/vírgulas) -> [] - dominio é NOT NULL DEFAULT '{}'
// (mecanismo de validação PRINCIPAL, desde a revisão de 16-08-2026),
// array vazio é o único jeito de dizer "sem restrição de domínio", não
// mais `null`.
function paraDominios(texto: string): string[] {
  return texto
    .split(',')
    .map((valor) => valor.trim())
    .filter(Boolean);
}

export function CriarTipoLink({ auth }: PropsPagina) {
  const navigate = useNavigate();
  const { mostrar } = useToast();
  const { erro, reportarErro, limparErro } = useErroToast();
  const [codigo, setCodigo] = useState('');
  const [nome, setNome] = useState('');
  const [regex, setRegex] = useState('');
  // Texto separado por vírgula na tela ("github.com, gist.github.com"),
  // não um array de verdade - sem componente de "tags" reutilizável no
  // projeto ainda, isto é o jeito mais simples de editar uma lista
  // pequena. Convertido pra array (nunca `null` - array vazio é o
  // default) só na hora de enviar (`aoCriar` abaixo). dominio é o
  // mecanismo de validação PRINCIPAL (array nativo do Postgres, NOT NULL
  // DEFAULT '{}') - um tipo pode aceitar mais de um domínio, ex.: GitHub
  // também responde em gist.github.com.
  const [dominioTexto, setDominioTexto] = useState('');
  // Mesmos defaults do banco (01_extensoes_enums_tabelas.sql) - a maioria
  // dos tipos cadastrados até hoje é só de identidade de perfil (Lattes,
  // ORCID, ResearchGate, LinkedIn), então já começar com permitePerfil
  // marcado poupa o clique mais comum.
  const [permitePerfil, setPermitePerfil] = useState(true);
  const [permiteAtualizacao, setPermiteAtualizacao] = useState(false);
  const [permiteRecompensa, setPermiteRecompensa] = useState(false);
  const [enviando, setEnviando] = useState(false);

  // Só valida depois que a pessoa digitou alguma coisa - mesmo raciocínio
  // de chaveInvalida em criar-configuracao.jsx.
  const codigoInvalido = codigo.length > 0 && !REGEX_CODIGO_VALIDO.test(codigo);
  const regexInvalida = regex.length > 0 && !regexValida(regex);
  // CK_TIPO_LINK_ALGUM_ESCOPO (01_extensoes_enums_tabelas.sql) - pelo
  // menos um dos 3 escopos precisa ficar marcado; o service confere isso
  // de novo no backend, isto é só pra travar o botão Criar ANTES de
  // bater lá.
  const nenhumEscopoMarcado = !permitePerfil && !permiteAtualizacao && !permiteRecompensa;

  const aoCriar = async (evento: FormEvent<HTMLFormElement>) => {
    evento.preventDefault();
    limparErro();
    setEnviando(true);
    try {
      const tipoCriado = await tipoLinkApi.criar(auth.authFetch, {
        codigo,
        nome,
        ...(regex ? { regex } : {}),
        dominio: paraDominios(dominioTexto),
        permitePerfil,
        permiteAtualizacao,
        permiteRecompensa,
      });
      mostrar(
        'Tipo de link cadastrado com sucesso.',
        `O novo tipo possui o ID: ${tipoCriado.idTipolink}`,
      );
      navigate(-1);
    } catch (erroRequisicao) {
      reportarErro(erroRequisicao);
    } finally {
      setEnviando(false);
    }
  };

  return (
    <CartaoFormulario
      icone="fa-link"
      titulo="Criar Tipo de Link"
      subtitulo="Preencha os dados abaixo para cadastrar um novo tipo de link."
    >
      <form onSubmit={aoCriar} className="p-10 space-y-6">
        {erro && <p className="text-red-700 text-sm font-bold text-center">{erro}</p>}

        <div>
          <label className="rotulo-campo">Código</label>
          <input
            type="text"
            value={codigo}
            onChange={(evento) => setCodigo(evento.target.value.toUpperCase())}
            required
            maxLength={20}
            placeholder="ex.: SITE_INSTITUCIONAL"
            aria-invalid={codigoInvalido}
            className={'input-padrao font-mono' + (codigoInvalido ? ' border-red-500' : '')}
          />
          {codigoInvalido ? (
            <p className="text-xs text-red-600 font-semibold mt-1">
              Só letras maiúsculas, números e underscore - sem espaço, minúscula ou acento.
            </p>
          ) : (
            <p className="text-xs texto-fraco mt-1">
              Identificador interno, nunca editável depois de criado (usado por regras internas
              do sistema - ex.: reconhecer Lattes/ORCID no cálculo de score).
            </p>
          )}
        </div>

        <div>
          <label className="rotulo-campo">Nome</label>
          <input
            type="text"
            value={nome}
            onChange={(evento) => setNome(evento.target.value)}
            required
            maxLength={100}
            placeholder="ex.: Site Institucional"
            className="input-padrao"
          />
        </div>

        <div>
          <label className="rotulo-campo">Domínios permitidos</label>
          <input
            type="text"
            value={dominioTexto}
            onChange={(evento) => setDominioTexto(evento.target.value)}
            placeholder="ex.: github.com, gist.github.com"
            className="input-padrao"
          />
          <p className="text-xs texto-fraco mt-1">
            Mecanismo de validação principal: o host da URL precisa estar nesta lista. Um ou mais
            domínios separados por vírgula. Deixe em branco pra aceitar qualquer domínio (ex.:
            "Outro").
          </p>
        </div>

        <div>
          <label className="rotulo-campo">Regex de validação (opcional)</label>
          <input
            type="text"
            value={regex}
            onChange={(evento) => setRegex(evento.target.value)}
            placeholder="ex.: ^https?://(www\.)?github\.com/[\w\-]+/?$"
            aria-invalid={regexInvalida}
            className={'input-padrao font-mono' + (regexInvalida ? ' border-red-500' : '')}
          />
          {regexInvalida ? (
            <p className="text-xs text-red-600 font-semibold mt-1">
              Isto não é uma expressão regular válida.
            </p>
          ) : (
            <p className="text-xs texto-fraco mt-1">
              Complemento opcional aos domínios acima - use só quando o domínio sozinho não
              garante uma URL válida (ex.: exigir um perfil específico, não a home do site). Deixe
              em branco quando o domínio já for suficiente.
            </p>
          )}
        </div>


        {/* Escopos - CK_TIPO_LINK_ALGUM_ESCOPO exige pelo menos um
            marcado (trg_valida_escopo_tipolink barra, na hora de gravar
            um link de verdade, qualquer tipo cujo campo correspondente
            aqui seja falso - 05_regras_negocio.sql [05-K-1]). */}
        <div>
          <label className="rotulo-campo">Onde este tipo pode ser usado</label>
          <div className="space-y-2 mt-1">
            <label className="flex items-center gap-2 text-sm font-semibold texto-padrao">
              <input
                type="checkbox"
                checked={permitePerfil}
                onChange={(evento) => setPermitePerfil(evento.target.checked)}
              />
              Perfil do pesquisador (links de identidade acadêmica)
            </label>
            <label className="flex items-center gap-2 text-sm font-semibold texto-padrao">
              <input
                type="checkbox"
                checked={permiteAtualizacao}
                onChange={(evento) => setPermiteAtualizacao(evento.target.checked)}
              />
              Atualização de campanha (prova de progresso)
            </label>
            <label className="flex items-center gap-2 text-sm font-semibold texto-padrao">
              <input
                type="checkbox"
                checked={permiteRecompensa}
                onChange={(evento) => setPermiteRecompensa(evento.target.checked)}
              />
              Recompensa (ex.: acesso antecipado a um repositório)
            </label>
          </div>
          {nenhumEscopoMarcado && (
            <p className="text-xs text-red-600 font-semibold mt-1">
              Pelo menos uma opção precisa ficar marcada.
            </p>
          )}
        </div>

        <div className="flex gap-3 pt-2">
          <button type="button" onClick={() => navigate(-1)} className="btn btn-secondary flex-1">
            Cancelar
          </button>
          <button
            type="submit"
            disabled={enviando || codigoInvalido || regexInvalida || nenhumEscopoMarcado}
            className="btn btn-primary flex-1"
          >
            {enviando ? 'Criando...' : 'Criar'}
          </button>
        </div>
      </form>
